#!/usr/bin/env python3
"""AI 세션 로그 수집기 명령줄 (AI-LOG-001, 1단계).

사용법 (저장소 루트에서):
  python -I scripts/ai_logging/cli.py install      치환 목록 생성(값은 출력하지 않음) 후 수집
  python -I scripts/ai_logging/cli.py sync         두 도구 원본 → 마스킹·검증 → ai-logs/live/
  python -I scripts/ai_logging/cli.py verify       사본이 원본의 마스킹 결과와 바이트 단위로 같은지 검사
  python -I scripts/ai_logging/cli.py verify --final   제출 직전 검사(원본보다 뒤처진 사본도 실패)
  python -I scripts/ai_logging/cli.py status       수집 상태·보류·hook 설정·Codex 신뢰 상태
  python -I scripts/ai_logging/cli.py index        세션을 첫 시각(UTC) 순으로 나열
  python -I scripts/ai_logging/cli.py submit [AI-LOG-002]   최종 수집·검증 후 ai-logs/live만 로그 전용 커밋
                                                   (모든 AI 응답이 끝난 뒤 일반 터미널에서 실행)
  python -I scripts/ai_logging/cli.py hook <claude|codex> <Event>   (hook 설정에서만 호출)

종료 코드: 0 정상, 1 보류·실패, 2 사용법 오류. hook 명령은 항상 0.
"""
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

from ailog import engine  # noqa: E402
from ailog.common import default_context  # noqa: E402


def _utf8_stdout():
    if not sys.stdout.isatty():
        try:
            sys.stdout.reconfigure(encoding="utf-8", errors="replace")
        except (AttributeError, ValueError):
            pass


def _print_problems(items, limit=30):
    for p in items[:limit]:
        loc = p.get("file", "")
        if "line" in p:
            loc += f":{p['line']}"
        print(f"    - [{p['rule']}] {p.get('session', '')} {loc} {p.get('detail', '')}".rstrip())
    if len(items) > limit:
        print(f"    ... 외 {len(items) - limit}건")


def _print_sync(r):
    print(f"수집 결과: {r['result']}  (정책 {r['policy_version']}, {r['time']})")
    for s in r["sessions"]:
        if s.get("status") == "original_missing":
            print(f"  {s['key']}: 원본을 찾을 수 없음 (사본 보존, 제출 보류 대상)")
            continue
        extra = ""
        if s.get("status") == "hold":
            extra = f" 보류 {s.get('problems')}건, 미반영 {s.get('pending_bytes')} bytes"
        else:
            extra = f" {s.get('lines')}줄 {s.get('original_bytes')} bytes, {s.get('first_timestamp')} ~ {s.get('last_timestamp')}"
        print(f"  {s['key']}: {s['status']}{extra}")
    if r["holds_total"]:
        print(f"  보류 항목 {r['holds_total']}건 (값은 표시하지 않음):")
        _print_problems(r["holds"])
    for e in r["errors"]:
        print(f"  오류: {e}")
    if r.get("unresolved_codex_files"):
        print(f"  참고: 프로젝트 여부를 판정하지 못한 Codex 파일 {r['unresolved_codex_files']}개(다른 프로젝트일 수 있음)")


def main(argv=None) -> int:
    argv = sys.argv[1:] if argv is None else argv
    ctx = default_context()
    cmd = argv[0] if argv else "status"
    if cmd == "hook":
        if len(argv) != 3:
            return 0
        return engine.hook(ctx, argv[1], argv[2])
    _utf8_stdout()
    if cmd == "install":
        r = engine.install(ctx)
        print(f"치환 목록: 총 {r['total']}개 (이번에 추가 {r['added']}개) - 값은 .ai-logging/mask-values.jsonl 에만 저장")
        for src, n in sorted(r["by_source"].items()):
            print(f"  {src}: {n}")
        rep = engine.sync(ctx)
        _print_sync(rep)
        return 0 if rep["result"] == "ok" else 1
    if cmd == "sync":
        rep = engine.sync(ctx)
        _print_sync(rep)
        return 0 if rep["result"] == "ok" else 1
    if cmd == "verify":
        final = "--final" in argv[1:]
        r = engine.verify(ctx, final=final)
        print(
            f"검증{'(최종)' if final else ''}: {'통과' if r['ok'] else '실패'} - 세션 {r['sessions_collected']}/{r['sessions_discovered']}, 파일 {r['files_checked']}개"
        )
        if r["failures"]:
            print("  실패:")
            _print_problems(r["failures"])
        if r["warnings"]:
            print("  참고(진행 중인 세션 등):")
            _print_problems(r["warnings"])
        return 0 if r["ok"] else 1
    if cmd == "status":
        st = engine.status(ctx)
        print(f"저장소: {st['root']}")
        print(f"치환 목록 항목: {st['mask_list_entries']}개")
        print(f"Claude hook 설정: {', '.join(st['claude_hooks_configured']) or '없음'}")
        print(f"Codex hook 설정: {', '.join(st['codex_hooks_configured']) or '없음'}")
        tr = st["codex_trust"]
        if not tr["readable"]:
            print("Codex hook 신뢰: 확인 불가(~/.codex/config.toml)")
        else:
            trusted = [k for k, v in sorted(tr["events"].items()) if v]
            print(f"Codex hook 신뢰: {', '.join(trusted) if trusted else '없음 - Codex에서 /hooks(또는 Settings > Hooks)로 검토·신뢰 필요'}")
        for tool, ev in sorted(st["last_hook_events"].items()):
            print(f"마지막 hook 실행({tool}): {ev['event']} {ev['time']}")
        if not st["last_hook_events"]:
            print("마지막 hook 실행: 기록 없음")
        if st["last_sync"]:
            _print_sync(st["last_sync"])
        else:
            print("수집 기록 없음 - install 실행 필요")
        for e in st["recent_errors"]:
            print(f"최근 hook 오류: {e.get('time')} {e.get('tool')} {e.get('event')} {e.get('error')} @ {e.get('where')}")
        return 0
    if cmd == "submit":
        task = argv[1] if len(argv) > 1 else "AI-LOG-002"
        print("주의: 모든 AI 응답이 끝난 뒤 일반 터미널에서 실행해야 마지막 대화까지 담깁니다.")
        r = engine.submit(ctx, task=task)
        if r.get("sync"):
            _print_sync(r["sync"])
        if r.get("verify"):
            _print_problems(r["verify"]["failures"])
        if not r["ok"]:
            print(f"제출 커밋 중단: {r['reason']} {r.get('detail', '')}".rstrip())
            return 1
        if r.get("committed"):
            print(f"제출 커밋 완료: {r['commit']} (세션 {r['sessions']}개, 파일 {r['files']}개)")
        else:
            print("변경 없음: 이미 최신 로그가 커밋되어 있습니다.")
        return 0
    if cmd == "index":
        for r in engine.build_index(ctx):
            print(f"{r['first_timestamp']}  {r['tool']:6}  {r['session_id']}  {r['main_lines']}줄  {r['path']}")
        return 0
    print(__doc__)
    return 2


if __name__ == "__main__":
    sys.exit(main())
def build_index(ctx: Context) -> list[dict]:
    rows = []
    for mpath in glob.glob(os.path.join(ctx.live_dir, "*", "*", "manifest.json")):
        m = read_json(mpath, None)
        if not m:
            continue
        rows.append(
            {
                "tool": m["tool"],
                "session_id": m["session_id"],
                "first_timestamp": m.get("first_timestamp"),
                "last_timestamp": m.get("last_timestamp"),
                "main_lines": m.get("main_lines"),
                "files": len(m.get("files", [])),
                "path": os.path.relpath(os.path.dirname(mpath), ctx.root).replace(os.sep, "/"),
            }
        )
    rows.sort(key=lambda r: (r["first_timestamp"] or "9999", r["tool"], r["session_id"]))
    write_json(ctx.index_path, {"time": utc_now(), "time_basis": "UTC", "sessions": rows})
    return rows


# --------------------------------------------------------------------- install
_EMAIL_TEXT_RE = re.compile(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}")


def extract_mask_values(ctx: Context, sessions: list[Session]) -> list[dict]:
    """원본에서 자동으로 기록되는 식별자를 찾아 치환 목록 후보를 만든다(값은 출력하지 않는다)."""
    found: dict[tuple, dict] = {}

    def add(kind, value, source):
        if isinstance(value, str) and len(value) >= 2:
            found.setdefault((kind, value), {"kind": kind, "value": value, "source": source})

    def add_email(value, source):
        add("literal", value, source)
        local = value.split("@", 1)[0]
        if len(local) >= 5:
            add("literal", local, source + ".local-part")

    for s in sessions:
        try:
            with open(s.main_path, "rb") as fh:
                lines = [fh.readline()] if s.tool == "codex" else fh.readlines()
        except OSError:
            continue
        for raw in lines:
            try:
                o = json.loads(raw)
            except ValueError:
                continue
            if not isinstance(o, dict):
                continue
            if s.tool == "codex" and o.get("type") == "session_meta":
                p = o.get("payload") or {}
                add("literal", p.get("creator_account_id"), "codex.session_meta.creator_account_id")
                add("literal", p.get("creator_user_id"), "codex.session_meta.creator_user_id")
            elif s.tool == "claude":
                t = o.get("type")
                if t == "session-owner":
                    add("literal", o.get("accountUuid"), "claude.session-owner.accountUuid")
                    add("literal", o.get("organizationUuid"), "claude.session-owner.organizationUuid")
                a = o.get("attachment") if isinstance(o.get("attachment"), dict) else None
                if a and a.get("type") == "session_context":
                    for em in _EMAIL_TEXT_RE.findall(json.dumps(a, ensure_ascii=False)):
                        add_email(em, "claude.session_context.email")
                if a and a.get("type") == "credential_org":
                    add("literal", a.get("organizationUuid"), "claude.credential_org.organizationUuid")
    git_email = git(ctx.root, "config", "user.email")
    if git_email and "@" in git_email:
        add_email(git_email, "git.user.email")
    home_user = os.path.basename(os.path.normpath(os.path.expanduser("~")))
    add("home_user", home_user, "os.home_directory_name")
    return list(found.values())


def install(ctx: Context) -> dict:
    ensure_dir(ctx.state_dir)
    ensure_dir(ctx.live_dir)

