def submit(ctx: Context, task: str = "AI-LOG-002", title: str = "세션 로그 제출") -> dict:
    """제출 커밋: 최종 수집 → 최종 검증 → ai-logs/live만 스테이징 → 현재 브랜치에 로그 전용 커밋.

    AI 세션 안에서 실행하면 그 뒤의 응답이 커밋에 빠지므로, 모든 AI 응답이 끝난 뒤 일반 터미널에서 실행한다.
    """
    if not re.fullmatch(r"[A-Za-z0-9]+-[A-Za-z0-9-]+", task):
        return {"ok": False, "reason": "task_id_format", "detail": "예: AI-LOG-002"}
    staged = git(ctx.root, "diff", "--cached", "--name-only")
    if staged is None:
        return {"ok": False, "reason": "not_a_git_repository"}
    if staged.strip():
        return {"ok": False, "reason": "other_changes_already_staged"}
    rep = sync(ctx)
    if rep["result"] != "ok":
        return {"ok": False, "reason": f"sync_{rep['result']}", "sync": rep}
    ver = verify(ctx, final=True)
    if not ver["ok"]:
        return {"ok": False, "reason": "final_verify_failed", "verify": ver}
    if git(ctx.root, "add", "-f", "--", LIVE_REL) is None:
        return {"ok": False, "reason": "git_add_failed"}
    names = [n for n in (git(ctx.root, "diff", "--cached", "--name-only") or "").splitlines() if n]
    stray = [n for n in names if not n.startswith(LIVE_REL + "/")]
    if stray:
        git(ctx.root, "reset", "-q", "--", *stray)
        return {"ok": False, "reason": "unexpected_paths_staged"}
    if not names:
        return {"ok": True, "committed": False, "reason": "nothing_to_commit"}
    body = [f"  세션 {len(rep['sessions'])}개의 마스킹 사본을 원본 전체 기준으로 반영 (최종 검증 통과)"]
    for s in rep["sessions"]:
        body.append(f"  - {s['key']}: {s.get('lines')}줄, 마지막 {s.get('last_timestamp')}")
    msg = f"[{task}] {title}\n\n" + "\n".join(body) + "\n"
    msg_path = os.path.join(ctx.state_dir, "submit-message.txt")
    atomic_write(msg_path, msg.encode("utf-8"))
    if git(ctx.root, "commit", "-q", "-F", msg_path, timeout=60) is None:
        return {"ok": False, "reason": "git_commit_failed"}
    head = git(ctx.root, "rev-parse", "--short", "HEAD")
    return {"ok": True, "committed": True, "commit": head, "files": len(names), "sessions": len(rep["sessions"])}


