"""공통 경로·입출력·잠금 유틸리티."""
from __future__ import annotations

import contextlib
import hashlib
import json
import os
import re
import subprocess
import time
from dataclasses import dataclass
from datetime import datetime, timezone

SCHEMA_VERSION = 1
# 정규식 밖의 검증 로직(임계값·판정 순서 등)이 바뀌면 올린다. 정규식 원문은 정책 버전에 자동 포함된다.
POLICY_CODE_VERSION = "3"


@dataclass
class Context:
    """수집기가 다루는 경로 묶음. 테스트에서는 임시 경로로 만든다."""

    root: str
    claude_home: str
    codex_home: str

    @property
    def state_dir(self) -> str:
        return os.path.join(self.root, ".ai-logging")

    @property
    def live_dir(self) -> str:
        return os.path.join(self.root, "ai-logs", "live")

    @property
    def allowlist_path(self) -> str:
        return os.path.join(self.root, "config", "ai-logs-allowlist.json")

    @property
    def mask_path(self) -> str:
        return os.path.join(self.state_dir, "mask-values.jsonl")

    @property
    def state_path(self) -> str:
        return os.path.join(self.state_dir, "state.json")

    @property
    def registry_path(self) -> str:
        return os.path.join(self.state_dir, "registry.jsonl")

    @property
    def last_sync_path(self) -> str:
        return os.path.join(self.state_dir, "last-sync.json")

    @property
    def errors_path(self) -> str:
        return os.path.join(self.state_dir, "errors.jsonl")

    @property
    def lock_path(self) -> str:
        return os.path.join(self.state_dir, "sync.lock")

    @property
    def index_path(self) -> str:
        return os.path.join(self.state_dir, "index.json")


def default_context() -> Context:
    here = os.path.dirname(os.path.abspath(__file__))
    root = os.environ.get("AI_LOGGING_ROOT") or os.path.dirname(os.path.dirname(os.path.dirname(here)))
    home = os.path.expanduser("~")
    claude_home = (
        os.environ.get("AI_LOGGING_CLAUDE_HOME")
        or os.environ.get("CLAUDE_CONFIG_DIR")
        or os.path.join(home, ".claude")
    )
    codex_home = os.environ.get("AI_LOGGING_CODEX_HOME") or os.environ.get("CODEX_HOME") or os.path.join(home, ".codex")
    return Context(root=root, claude_home=claude_home, codex_home=codex_home)


_POSIX_DRIVE = re.compile(r"^/([a-zA-Z])(?:/|$)")


def norm_path(p: str) -> str:
    """경로 비교용 정규화. Git Bash 형식(/c/...)도 Windows 경로로 바꾼다."""
    if os.name == "nt":
        m = _POSIX_DRIVE.match(p)
        if m:
            p = m.group(1) + ":\\" + p[m.end():]
    return os.path.normcase(os.path.normpath(p))


def is_within(path: str, root: str) -> bool:
    n, r = norm_path(path), norm_path(root)
    return n == r or n.startswith(r.rstrip("\\/") + os.sep)


def sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def utc_now() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%f")[:-3] + "Z"


def ensure_dir(path: str) -> None:
    os.makedirs(path, exist_ok=True)


def atomic_write(path: str, data: bytes) -> None:
    """같은 폴더의 임시 파일에 쓴 뒤 교체한다. Windows 일시 잠금은 재시도한다."""
    ensure_dir(os.path.dirname(path))
    tmp = f"{path}.tmp-{os.getpid()}"
    with open(tmp, "wb") as f:
        f.write(data)
        f.flush()
        os.fsync(f.fileno())
    for attempt in range(20):
        try:
            os.replace(tmp, path)
            return
        except PermissionError:
            if attempt == 19:
                raise
            time.sleep(0.1)


def dumps_json(obj) -> bytes:
    """결정적인 JSON 직렬화(키 정렬, LF). manifest·상태 파일 전용."""
    return (json.dumps(obj, ensure_ascii=False, indent=2, sort_keys=True) + "\n").encode("utf-8")


def read_json(path: str, default):
    try:
        with open(path, "rb") as f:
            return json.loads(f.read().decode("utf-8"))
    except FileNotFoundError:
        return default
    except (ValueError, UnicodeDecodeError):
        # 손상된 상태 파일은 덮어쓰지 않고 따로 보관한 뒤 기본값으로 진행한다.
        with contextlib.suppress(OSError):
            os.replace(path, f"{path}.corrupt-{int(time.time())}")
        return default


def write_json(path: str, obj) -> None:
    atomic_write(path, dumps_json(obj))


def append_jsonl(path: str, obj) -> None:
    ensure_dir(os.path.dirname(path))
    line = json.dumps(obj, ensure_ascii=False, sort_keys=True) + "\n"
    with open(path, "ab") as f:
        f.write(line.encode("utf-8"))


class LockTimeout(Exception):
    pass


@contextlib.contextmanager
def file_lock(path: str, timeout: float = 60.0, stale_after: float = 600.0):
    """O_EXCL 파일 잠금. 오래된 잠금(stale_after초)은 비정상 종료로 보고 회수한다."""
    ensure_dir(os.path.dirname(path))
    start = time.time()
    while True:
        try:
            fd = os.open(path, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
            os.write(fd, f"{os.getpid()} {utc_now()}".encode())
            os.close(fd)
            break
        except FileExistsError:
            try:
                if time.time() - os.path.getmtime(path) > stale_after:
                    os.remove(path)
                    continue
            except FileNotFoundError:
                continue
            if time.time() - start > timeout:
                raise LockTimeout(path)
            time.sleep(0.2)
    try:
        yield
    finally:
        with contextlib.suppress(FileNotFoundError):
            os.remove(path)


def git(root: str, *args: str, timeout: float = 10.0):
    """git 명령의 표준 출력. 실패하면 None."""
    try:
        r = subprocess.run(
            ["git", "-C", root, *args],
            capture_output=True,
            timeout=timeout,
            check=False,
        )
    except (OSError, subprocess.SubprocessError):
        return None
    if r.returncode != 0:
        return None
    return r.stdout.decode("utf-8", "replace").strip()

"""두 도구의 네이티브 세션 원본 탐색.

판정은 폴더 이름이 아니라 기록 안의 cwd 값으로 한다. Claude 프로젝트 폴더 이름은
'_'를 '-'로 바꿔 만들기 때문에 다른 경로와 겹칠 수 있다.
"""
from __future__ import annotations

import json
import os
import re
from dataclasses import dataclass, field

from .common import Context, git, is_within, norm_path

_UUID_RE = re.compile(r"[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}")
_REF_KEY_RE = re.compile(r"(parent|fork|source|thread)", re.IGNORECASE)

# cwd를 찾기 위해 한 파일에서 읽는 최대 범위
_MAX_SCAN_LINES = 2000
_MAX_SCAN_BYTES = 8 * 1024 * 1024


@dataclass
class SessionFile:
    rel: str  # 세션 기준 상대 경로(POSIX 구분자). 사본 경로에 그대로 쓴다.
    path: str  # 원본 절대 경로
    role: str  # "main" | "attachment"


@dataclass
class Session:
    tool: str
    session_id: str
    main_path: str
    files: list[SessionFile] = field(default_factory=list)

    @property
    def key(self) -> str:
        return f"{self.tool}/{self.session_id}"


@dataclass
class Discovery:
    sessions: list[Session]
    unresolved: int  # cwd도 부모 연결도 확인하지 못한 Codex 파일 수
    roots: list[str]


def project_roots(ctx: Context, state: dict) -> list[str]:
    roots = [ctx.root]
    out = git(ctx.root, "worktree", "list", "--porcelain")
    if out:
        for line in out.splitlines():
            if line.startswith("worktree "):
                roots.append(line[len("worktree "):].strip())
    roots.extend(state.get("extra_roots", []))
    seen, uniq = set(), []
    for r in roots:
        n = norm_path(r)
        if n not in seen:
            seen.add(n)
            uniq.append(r)
    return uniq


def _in_roots(cwd, roots) -> bool:
    return isinstance(cwd, str) and any(is_within(cwd, r) for r in roots)


def _read_claude_cwd(path: str):
    read = 0
    with open(path, "rb") as f:
        for i, line in enumerate(f):
            read += len(line)
            if i >= _MAX_SCAN_LINES or read > _MAX_SCAN_BYTES:
                break
            try:
                o = json.loads(line)
            except ValueError:
                continue
            if isinstance(o, dict) and isinstance(o.get("cwd"), str):
                return o["cwd"]
    return None


def _collect_refs(obj, depth=0, under_ref_key=False, out=None):
    out = set() if out is None else out
    if depth > 3:
        return out
    if isinstance(obj, dict):
        for k, v in obj.items():
            _collect_refs(v, depth + 1, under_ref_key or bool(_REF_KEY_RE.search(str(k))), out)
    elif isinstance(obj, list):
        for v in obj[:20]:
            _collect_refs(v, depth + 1, under_ref_key, out)
    elif isinstance(obj, str) and under_ref_key:
        out.update(m.group(0).lower() for m in _UUID_RE.finditer(obj))
    return out


def _read_codex_meta(path: str):
    with open(path, "rb") as f:
        first = f.readline()
    try:
        o = json.loads(first)
    except ValueError:
        return None
    if not isinstance(o, dict) or o.get("type") != "session_meta":
        return None
    p = o.get("payload") if isinstance(o.get("payload"), dict) else {}
    sid = p.get("id") or p.get("session_id")
    if not isinstance(sid, str):
        m = _UUID_RE.search(os.path.basename(path))
        sid = m.group(0) if m else None
    refs = sorted(_collect_refs(p) - ({sid.lower()} if sid else set()))
    return {"cwd": p.get("cwd") if isinstance(p.get("cwd"), str) else None, "id": sid, "refs": refs}


def _cached(cache: dict, path: str, loader):
    """경로별 메타데이터 캐시. cwd를 찾은 경우에만 저장한다(새 파일은 다시 읽는다)."""
    hit = cache.get(path)
    if hit is not None:
        return hit
    try:
        value = loader(path)
    except OSError:
        return None
    if value is not None and (not isinstance(value, dict) or value.get("cwd") or value.get("refs")):
        cache[path] = value
    return value


def _is_plain_file(p: str) -> bool:
    return os.path.isfile(p) and not os.path.islink(p)


def discover_claude(ctx: Context, roots: list[str], cache: dict) -> list[Session]:
    base = os.path.join(ctx.claude_home, "projects")
    if not os.path.isdir(base):
        return []
    sessions = []
    for proj in sorted(os.listdir(base)):
        pdir = os.path.join(base, proj)
        if not os.path.isdir(pdir) or os.path.islink(pdir):
            continue
        for name in sorted(os.listdir(pdir)):
            fpath = os.path.join(pdir, name)
            if not name.endswith(".jsonl") or not _is_plain_file(fpath):
                continue
            meta = _cached(cache, fpath, lambda p: {"cwd": _read_claude_cwd(p)})
            if not meta or not _in_roots(meta.get("cwd"), roots):
                continue
            sid = name[: -len(".jsonl")]
            s = Session("claude", sid, fpath, [SessionFile(name, fpath, "main")])
            sdir = os.path.join(pdir, sid)
            if os.path.isdir(sdir) and not os.path.islink(sdir):
                for dirpath, dirnames, filenames in os.walk(sdir, followlinks=False):
                    dirnames[:] = sorted(d for d in dirnames if not os.path.islink(os.path.join(dirpath, d)))
                    for fn in sorted(filenames):
                        fp = os.path.join(dirpath, fn)
                        if fn.endswith(".tmp") or ".tmp-" in fn or not _is_plain_file(fp):
                            continue
                        rel = os.path.relpath(fp, pdir).replace(os.sep, "/")
                        s.files.append(SessionFile(rel, fp, "attachment"))
            sessions.append(s)
    return sessions


def discover_codex(ctx: Context, roots: list[str], cache: dict):
    found = []  # (path, meta)
    for sub in ("sessions", "archived_sessions"):
        base = os.path.join(ctx.codex_home, sub)
        if not os.path.isdir(base):
            continue
        for dirpath, dirnames, filenames in os.walk(base, followlinks=False):
            dirnames.sort()
            for fn in sorted(filenames):
                fp = os.path.join(dirpath, fn)
                if fn.startswith("rollout-") and fn.endswith(".jsonl") and _is_plain_file(fp):
                    meta = _cached(cache, fp, _read_codex_meta)
                    found.append((fp, meta))
    included: dict[str, Session] = {}
    pending = []
    for fp, meta in found:
        if meta and meta.get("id") and _in_roots(meta.get("cwd"), roots):
            sid = meta["id"]
            included.setdefault(sid, Session("codex", sid, fp, [SessionFile(os.path.basename(fp), fp, "main")]))
        elif meta and meta.get("id") and not meta.get("cwd"):
            pending.append((fp, meta))
    # cwd가 없는 하위 rollout은 이미 포함된 세션을 참조할 때만 포함한다(반복 적용).
    changed = True
    known = {k.lower() for k in included}
    while changed:
        changed = False
        rest = []
        for fp, meta in pending:
            if set(meta.get("refs", [])) & known:
                sid = meta["id"]
                included.setdefault(sid, Session("codex", sid, fp, [SessionFile(os.path.basename(fp), fp, "main")]))
                known.add(sid.lower())
                changed = True
            else:
                rest.append((fp, meta))
        pending = rest
    unresolved = sum(1 for fp, meta in found if not meta or not meta.get("id"))
    unresolved += len(pending)
    return list(included.values()), unresolved


def discover(ctx: Context, state: dict) -> Discovery:
    cache = state.setdefault("meta_cache", {})
    roots = project_roots(ctx, state)
    claude = discover_claude(ctx, roots, cache)
    codex, unresolved = discover_codex(ctx, roots, cache)
    return Discovery(sessions=claude + codex, unresolved=unresolved, roots=roots)

