"""불변 스냅샷과 로그 전용 커밋.

경로: ai-logs/snapshots/<tool>/<session-id>/<policy-version>/L<원본 바이트 20자리>-<sha256 앞 16자리>/
  manifest.json  + files/<원본 상대 경로>  (세션의 모든 파일 전체 사본, 마스킹만 적용)

- 같은 원본·같은 정책이면 같은 ID(폴더 이름)가 나온다. 생성 시각 같은 가변 값은 manifest에 넣지 않는다.
- 전체 sha256은 manifest의 snapshot_sha256에 기록한다(폴더 이름에는 앞 16자리만).
- 이미 있는 폴더는 고치지 않는다. 같은 ID인데 내용이 다르면 보류한다.
- 원본 길이가 같은데 내용(해시)이 다른 스냅샷은 '더 최신'으로 추정하지 않고 보류한다.
- 원본 앞부분 불변성(절단·재작성·삭제)은 이전 스냅샷·live·상태 기록 모두와 대조한다.
"""
from __future__ import annotations

import json
import os

from .common import (
    LARGE_FILE_BYTES,
    SCHEMA_VERSION,
    SNAPSHOTS_REL,
    Context,
    GitError,
    atomic_write,
    dumps_json,
    file_lock,
    read_json_ro,
    sha256,
    utc_now,
)
from .discover import Session, resolve_targets

TIME_BASIS = "UTC - 도구가 기록한 ISO 8601 timestamp 값을 그대로 사용"
ORDER_BASIS = "파일 안의 줄 순서 (타임스탬프로 재정렬하지 않음)"


# ------------------------------------------------------------------ identity
def _id_payload(m: dict) -> bytes:
    files = sorted(
        [e["path"], e["original_bytes"], e["original_sha256"], e["copy_sha256"]] for e in m.get("files", [])
    )
    payload = {
        "schema": m.get("schema"),
        "tool": m.get("tool"),
        "session_id": m.get("session_id"),
        "policy_version": m.get("policy_version"),
        "files": files,
    }
    return json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")


def snapshot_sha256(m: dict) -> str:
    return sha256(_id_payload(m))


def snapshot_id(m: dict) -> str:
    """manifest 내용으로 ID를 다시 계산한다(경로를 믿지 않는다)."""
    total = sum(int(e["original_bytes"]) for e in m.get("files", []))
    return "L%020d-%s" % (total, snapshot_sha256(m)[:16])


def snap_base(tool: str, sid: str, policy: str, sid_: str) -> str:
    return f"{SNAPSHOTS_REL}/{tool}/{sid}/{policy}/{sid_}/"


# ------------------------------------------------------------ known snapshots
def worktree_manifests(ctx: Context) -> dict[str, dict]:
    """작업 폴더의 스냅샷 manifest {base 경로: manifest}. 읽을 수 없는 manifest는 base만 표시(None)."""
    out: dict[str, dict] = {}
    root = ctx.snapshots_dir
    if not os.path.isdir(root):
        return out
    for tool in sorted(os.listdir(root)):
        for sid in sorted(_dirs(os.path.join(root, tool))):
            for pol in sorted(_dirs(os.path.join(root, tool, sid))):
                for snap in sorted(_dirs(os.path.join(root, tool, sid, pol))):
                    m, st = read_json_ro(os.path.join(root, tool, sid, pol, snap, "manifest.json"))
                    out[snap_base(tool, sid, pol, snap)] = m if st == "ok" and isinstance(m, dict) else None
    return out


def _dirs(path: str) -> list[str]:
    try:
        return [d for d in os.listdir(path) if os.path.isdir(os.path.join(path, d))]
    except OSError:
        return []


def tree_manifests(root: str, treeish: str) -> dict[str, dict]:
    """커밋 트리 안의 스냅샷 manifest {base 경로: manifest}(Git blob에서 읽음)."""
    from . import gitops

    files = gitops.tree_files(root, treeish, SNAPSHOTS_REL)
    mans = {p: oid for p, (_, oid) in files.items() if p.endswith("/manifest.json")}
    blobs = gitops.cat_blobs(root, mans.values())
    out = {}
    for path, oid in mans.items():
        base = path[: -len("manifest.json")]
        try:
            out[base] = json.loads(blobs[oid].decode("utf-8"))
        except (KeyError, ValueError, UnicodeDecodeError):
            out[base] = None
    return out


def known_manifests(ctx: Context, refs=()) -> dict[str, dict]:
    """작업 폴더 + 주어진 커밋들의 스냅샷 manifest 합집합."""
    out = {}
    for ref in refs:
        try:
            out.update({k: v for k, v in tree_manifests(ctx.root, ref).items() if k not in out or out[k] is None})
        except GitError:
            continue
    for k, v in worktree_manifests(ctx).items():
        if k not in out or out[k] is None:
            out[k] = v
    return out


def by_session(manifests: dict[str, dict]) -> dict[str, list[tuple[str, dict]]]:
    out: dict[str, list] = {}
    for base, m in manifests.items():
        parts = base.rstrip("/").split("/")
        out.setdefault(f"{parts[-4]}/{parts[-3]}", []).append((base, m))
    return out


def latest(entries: list[tuple[str, dict]], policy_version: str):
    """정책별 최신 스냅샷: 원본 바이트가 가장 큰 것. 같은 길이에 다른 ID가 있으면 (None, 'ambiguous')."""
    cands = [(b, m) for b, m in entries if m and m.get("policy_version") == policy_version]
    if not cands:
        return None, "none"
    top = max(m.get("original_bytes_total", -1) for _, m in cands)
    tops = {m.get("snapshot_id") for _, m in cands if m.get("original_bytes_total") == top}
    if len(tops) > 1:
        return None, "ambiguous"
    return next((b, m) for b, m in cands if m.get("original_bytes_total") == top), "ok"


# ------------------------------------------------------------------- create
def _prefix_problems(rel: str, data: bytes, prior: list[tuple[int, str]]) -> list[str]:
    out = []
    for n, h in sorted(set(prior)):
        if len(data) < n:
            out.append("original_truncated")
        elif sha256(data[:n]) != h:
            out.append("original_rewritten")
    return sorted(set(out))


def _prior_knowledge(session_key: str, state: dict, snaps: list[tuple[str, dict]]) -> dict[str, list]:
    """파일별 (원본 바이트, 앞부분 sha256) 기록: 상태(live 수집) + 모든 이전 스냅샷."""
    prior: dict[str, list] = {}
    prefix = session_key + "/"
    for k, v in (state.get("files") or {}).items():
        if k.startswith(prefix) and isinstance(v.get("original_bytes"), int) and v.get("original_sha256"):
            prior.setdefault(k[len(prefix):], []).append((v["original_bytes"], v["original_sha256"]))
    for _, m in snaps:
        for e in (m or {}).get("files", []):
            if isinstance(e.get("original_bytes"), int) and e.get("original_sha256"):
                prior.setdefault(e["path"], []).append((e["original_bytes"], e["original_sha256"]))
    return prior


def build_snapshot(ctx: Context, s: Session, policy, state: dict, snaps: list[tuple[str, dict]],
                   idle: bool) -> dict:
    """세션 하나의 스냅샷을 준비한다(쓰지 않음). 결과: {status: ready|hold, manifest, copies, problems, ...}.

    개행 없는 마지막 JSONL 기록: 세션이 idle로 확인되고 그 꼬리가 JSON으로 파싱되면 '종료된 유효 기록'으로
    포함한다. 그 밖에는 마지막 개행까지만 담고 deferred_tail로 보고한다(최종 완전성 검사는 실패한다).
    """
    from .engine import check_masked, jsonl_stats, read_full

    problems, warnings, deferred = [], [], []
    prior = _prior_knowledge(s.key, state, snaps)
    entries, copies = [], {}
    current = {f.rel for f in s.files}
    for rel in sorted(set(prior) - current):
        problems.append({"rule": "original_file_deleted", "file": rel})
    main_stats = (0, None, None)
    for f in s.files:
        try:
            data = read_full(f)
        except OSError as e:
            problems.append({"rule": "original_unreadable", "file": f.rel, "detail": type(e).__name__})
            continue
        ends_open = False
        if f.rel.endswith(".jsonl") and data and not data.endswith(b"\n"):
            cut = data.rfind(b"\n") + 1
            tail = data[cut:]
            try:
                json.loads(tail)
                tail_ok = True
            except ValueError:
                tail_ok = False
            if idle and tail_ok:
                ends_open = True
            else:
                deferred.append({"file": f.rel, "bytes": len(tail), "reason": "unterminated_tail"})
                data = data[:cut]
        for rule in _prefix_problems(f.rel, data, prior.get(f.rel, [])):
            problems.append({"rule": rule, "file": f.rel})
        masked, counts = policy.mask(data)
        for p in check_masked(f.rel, data, masked, policy):
            problems.append(p)
        if len(data) > LARGE_FILE_BYTES:
            warnings.append({"rule": "large_file", "file": f.rel, "detail": f"bytes={len(data)}"})
        entry = {
            "path": f.rel,
            "role": f.role,
            "original_bytes": len(data),
            "original_sha256": sha256(data),
            "copy_bytes": len(masked),
            "copy_sha256": sha256(masked),
            "masked": dict(sorted(counts.items())),
        }
        if f.rel.endswith(".jsonl"):
            n, first, last, bad = jsonl_stats(data)
            entry["lines"] = n
            entry["ends_without_newline"] = ends_open
            if bad:
                entry["non_json_lines"] = bad[:50]
            if f.role == "main":
                main_stats = (n, first, last)
        entries.append(entry)
        copies[f.rel] = masked
    entries.sort(key=lambda e: (e["role"] != "main", e["path"]))
    n, first, last = main_stats
    m = {
        "schema": SCHEMA_VERSION,
        "kind": "snapshot",
        "tool": s.tool,
        "session_id": s.session_id,
        "policy_version": policy.version,
        "time_basis": TIME_BASIS,
        "order_basis": ORDER_BASIS,
        "first_timestamp": first,
        "last_timestamp": last,
        "main_lines": n,
        "original_bytes_total": sum(e["original_bytes"] for e in entries),
        "files": entries,
        "warnings": warnings,
    }
    m["snapshot_sha256"] = snapshot_sha256(m)
    m["snapshot_id"] = snapshot_id(m)
    # 같은 정책에서 같은 길이·다른 내용, 또는 더 긴 스냅샷이 이미 있는데 지금이 더 짧은 경우
    for base, old in snaps:
        if not old or old.get("policy_version") != policy.version:
            continue
        if old.get("original_bytes_total") == m["original_bytes_total"] and old.get("snapshot_id") != m["snapshot_id"]:
            problems.append({"rule": "same_length_different_snapshot", "detail": base})
    status = "hold" if problems else "ready"
    return {"key": s.key, "status": status, "manifest": m, "copies": copies, "problems": problems,
            "warnings": warnings, "deferred": deferred,
            "base": snap_base(s.tool, s.session_id, policy.version, m["snapshot_id"])}


def write_snapshot(ctx: Context, prep: dict) -> str:
    """준비된 스냅샷을 쓴다. 이미 있으면 내용이 같은지 확인만 한다. 반환: created|exists|conflict."""
    base_abs = os.path.join(ctx.root, *prep["base"].rstrip("/").split("/"))
    mpath = os.path.join(base_abs, "manifest.json")
    want = dumps_json(prep["manifest"])
    if os.path.exists(mpath):
        with open(mpath, "rb") as f:
            have = f.read()
        if have != want:
            return "conflict"
        for rel, data in prep["copies"].items():
            p = os.path.join(base_abs, "files", *rel.split("/"))
            try:
                with open(p, "rb") as f:
                    if f.read() != data:
                        return "conflict"
            except FileNotFoundError:
                return "conflict"
        return "exists"
    for rel, data in prep["copies"].items():
        atomic_write(os.path.join(base_abs, "files", *rel.split("/")), data)
    atomic_write(mpath, want)  # manifest를 마지막에 써서 '완성된 폴더'의 표시로 삼는다
    return "created"


def snapshot_all(ctx: Context, refs=("HEAD",), states: dict | None = None) -> dict:
    """대상 세션 전체 스냅샷. 보류가 하나라도 있으면 그 세션은 쓰지 않는다."""
    from .engine import build_policy, load_state

    with file_lock(ctx.lock_path, timeout=60):
        state = load_state(ctx)
        policy = build_policy(ctx)
        known = known_manifests(ctx, refs)
        grouped = by_session(known)
        targets = resolve_targets(ctx, state, extra_known=grouped.keys())
        report = {"time": utc_now(), "policy_version": policy.version, "sessions": [], "holds": [],
                  "warnings": [], "missing": [], "result": "ok"}
        if not os.path.exists(ctx.mask_path):
            report.update(result="error", error="mask_list_missing")
            return report
        for s in targets.sessions:
            idle = bool(states and states.get(s.key, {}).get("state") == "idle")
            prep = build_snapshot(ctx, s, policy, state, grouped.get(s.key, []), idle)
            row = {"key": s.key, "base": prep["base"], "status": prep["status"],
                   "original_bytes": prep["manifest"]["original_bytes_total"],
                   "main_lines": prep["manifest"]["main_lines"],
                   "last_timestamp": prep["manifest"]["last_timestamp"]}
            if prep["deferred"]:
                row["deferred"] = prep["deferred"]
            if prep["status"] == "ready":
                row["status"] = write_snapshot(ctx, prep)
                if row["status"] == "conflict":
                    report["holds"].append({"rule": "snapshot_dir_conflict", "session": s.key})
            else:
                report["holds"].extend(dict(p, session=s.key) for p in prep["problems"])
            report["warnings"].extend(dict(w, session=s.key) for w in prep["warnings"])
            report["sessions"].append(row)
        for key in targets.missing:
            has = bool(grouped.get(key))
            report["missing"].append({"session": key, "snapshot_kept": has})
        if report["holds"]:
            report["result"] = "hold"
        return report


# ------------------------------------------------------------- completeness
def completeness(ctx: Context, treeish: str | None, policy=None, read_originals: bool = True) -> dict:
    """커밋(또는 작업 폴더) 기준 제출 완전성.

    모든 대상 세션에 대해, 현재 정책의 최신 스냅샷이 원본 파일 전체(EOF)와 같은지 확인한다.
    failures가 비어 있어야 '완전'이다. 원본이 사라진 세션은 이전 스냅샷이 있으면 경고, 없으면 실패.
    """
    from .engine import build_policy, load_state

    policy = policy or build_policy(ctx)
    mans = tree_manifests(ctx.root, treeish) if treeish else worktree_manifests(ctx)
    grouped = by_session(mans)
    state = load_state(ctx)
    targets = resolve_targets(ctx, state, extra_known=grouped.keys())
    failures, warnings, rows = [], [], []
    for base, m in mans.items():
        if m is None:
            failures.append({"rule": "snapshot_manifest_unreadable", "detail": base})
    for s in targets.sessions:
        b, how = latest(grouped.get(s.key, []), policy.version)
        if b is None:
            failures.append({"rule": "snapshot_missing" if how == "none" else "snapshot_ambiguous", "session": s.key})
            continue
        m = mans[b]
        listed = {e["path"]: e for e in m["files"]}
        cur = {f.rel: f for f in s.files}
        for rel in sorted(set(cur) - set(listed)):
            failures.append({"rule": "file_not_in_snapshot", "session": s.key, "file": rel})
        if read_originals:
            for rel, e in listed.items():
                f = cur.get(rel)
                if f is None:
                    failures.append({"rule": "original_file_deleted", "session": s.key, "file": rel})
                    continue
                try:
                    size = os.path.getsize(f.path)
                    with open(f.path, "rb") as fh:
                        head = fh.read(e["original_bytes"])
                except OSError:
                    failures.append({"rule": "original_unreadable", "session": s.key, "file": rel})
                    continue
                if size < e["original_bytes"] or sha256(head) != e["original_sha256"]:
                    failures.append({"rule": "original_changed", "session": s.key, "file": rel})
                elif size > e["original_bytes"]:
                    failures.append({"rule": "snapshot_behind_original", "session": s.key, "file": rel,
                                     "detail": f"bytes={size - e['original_bytes']}"})
        rows.append({"key": s.key, "snapshot": b, "original_bytes": m.get("original_bytes_total")})
    for key in targets.missing:
        if grouped.get(key):
            warnings.append({"rule": "original_missing_snapshot_kept", "session": key})
        else:
            failures.append({"rule": "original_missing_not_snapshotted", "session": key})
    if targets.unresolved:
        warnings.append({"rule": "unresolved_codex_files", "detail": f"count={targets.unresolved}"})
    return {"treeish": treeish or "worktree", "policy_version": policy.version, "sessions": rows,
            "failures": failures, "warnings": warnings, "complete": not failures}


def scan_tree_secrets(ctx: Context, treeish: str, policy=None) -> list[dict]:
    """커밋 트리의 모든 스냅샷 blob을 현재 정책으로 다시 검사한다(치환 목록 잔류·민감정보 후보).

    이미 커밋된 값은 새 마스킹 커밋으로 지워지지 않는다. 발견되면 게시를 멈추고 보고한다.
    """
    from . import gitops
    from .engine import build_policy

    policy = policy or build_policy(ctx)
    files = gitops.tree_files(ctx.root, treeish, SNAPSHOTS_REL)
    blobs = gitops.cat_blobs(ctx.root, {oid for p, (_, oid) in files.items() if "/files/" in p})
    out = []
    for path, (_, oid) in sorted(files.items()):
        if "/files/" not in path:
            continue
        data = blobs.get(oid, b"")
        if policy.residue(data):
            out.append({"rule": "committed_mask_residue", "file": path})
        for h in policy.detect(data):
            out.append({"rule": "committed_" + h.rule, "file": path, "line": h.line})
    return out


# ------------------------------------------------------------ live coverage
def live_covered(ctx: Context) -> dict:
    """live 사본 ⊆ 스냅샷: live 제외 정책으로 바꾸기 전 확인.

    각 live 파일에 대해 같은 세션의 최신 스냅샷(정책 무관, 원본 바이트 최대)이 live보다 길거나 같고,
    현재 원본 기준으로 두 범위가 모두 같은 원본의 앞부분이며, 같은 정책이면 스냅샷 사본이 live 사본으로 시작한다.
    """
    import glob

    snaps = by_session(worktree_manifests(ctx))
    gaps, checked = [], 0
    for mpath in glob.glob(os.path.join(ctx.live_dir, "*", "*", "manifest.json")):
        m, st = read_json_ro(mpath)
        if st != "ok":
            gaps.append({"rule": "live_manifest_unreadable", "detail": os.path.basename(os.path.dirname(mpath))})
            continue
        key = f"{m['tool']}/{m['session_id']}"
        cands = [x for x in snaps.get(key, []) if x[1]]
        for e in m["files"]:
            checked += 1
            best = None
            for base, sm in cands:
                se = next((x for x in sm["files"] if x["path"] == e["path"]), None)
                if se and se["original_bytes"] >= e["original_bytes"]:
                    if best is None or se["original_bytes"] > best[1]["original_bytes"]:
                        best = (base, se, sm)
            if best is None:
                gaps.append({"rule": "live_not_in_snapshot", "session": key, "file": e["path"]})
                continue
            base, se, sm = best
            live_copy = os.path.join(os.path.dirname(mpath), "files", *e["path"].split("/"))
            snap_copy = os.path.join(ctx.root, *base.rstrip("/").split("/"), "files", *e["path"].split("/"))
            if sm.get("policy_version") == m.get("policy_version"):
                with open(live_copy, "rb") as a, open(snap_copy, "rb") as b:
                    if not b.read().startswith(a.read()):
                        gaps.append({"rule": "snapshot_not_extending_live", "session": key, "file": e["path"]})
            # 정책이 다르면 원본 기준으로 대조: live 범위와 스냅샷 범위가 같은 원본의 앞부분이어야 한다
            orig = _original_path(ctx, key, e["path"])
            if orig:
                with open(orig, "rb") as f:
                    data = f.read(se["original_bytes"])
                if sha256(data[: e["original_bytes"]]) != e["original_sha256"] or sha256(data) != se["original_sha256"]:
                    gaps.append({"rule": "live_snapshot_original_mismatch", "session": key, "file": e["path"]})
            elif sm.get("policy_version") != m.get("policy_version"):
                gaps.append({"rule": "original_missing_cannot_compare", "session": key, "file": e["path"]})
    return {"files_checked": checked, "gaps": gaps, "covered": not gaps}


def _original_path(ctx: Context, key: str, rel: str):
    from .engine import load_state

    targets = resolve_targets(ctx, load_state(ctx))
    for s in targets.sessions:
        if s.key == key:
            for f in s.files:
                if f.rel == rel:
                    return f.path
    return None


# ---------------------------------------------------------------- commit
def _message(task: str, title: str, rows: list[dict], policy_version: str, added: list[str]) -> str:
    body = [f"  스냅샷 {len(added)}개 추가 (정책 {policy_version}, 세션 {len(rows)}개 확인)"]
    for r in rows:
        if r["base"] in added:
            body.append(f"  - {r['key']}: {r['base'].rstrip('/').split('/')[-1]}, {r['main_lines']}줄, "
                        f"마지막 {r['last_timestamp']}")
    return f"[{task}] {title}\n\n" + "\n".join(body) + "\n"


def commit_snapshots(ctx: Context, task: str, title: str, *, expect_branch: str | None = None,
                     expect_head: str | None = None, states: dict | None = None, require_complete: bool = False) -> dict:
    """현재 브랜치에 로그 전용 커밋(부모 1개)을 만든다. 사용자 index·작업 폴더의 다른 항목은 바꾸지 않는다.

    보류 조건: 분리된 HEAD, 진행 중인 Git 작업, 스테이징된 변경, 예상과 다른 브랜치·HEAD.
    변경할 스냅샷이 없으면 커밋하지 않는다(빈 커밋 금지).
    """
    from . import gitops, rules

    root = ctx.root
    branch = gitops.current_branch(root)
    head = gitops.rev(root, "HEAD")
    if not branch:
        return {"ok": False, "reason": "detached_head"}
    if expect_branch and branch != expect_branch:
        return {"ok": False, "reason": "branch_changed", "detail": f"{expect_branch}->{branch}"}
    if expect_head and head != expect_head:
        return {"ok": False, "reason": "head_changed"}
    busy = gitops.in_progress(root)
    if busy:
        return {"ok": False, "reason": "git_operation_in_progress", "detail": ",".join(busy)}
    if gitops.staged_changes(root):
        return {"ok": False, "reason": "staged_changes_present"}
    if not rules.TASK_ID_RE.match(task or ""):
        return {"ok": False, "reason": "task_id_format", "detail": "예: AI-LOG-001"}
    rep = snapshot_all(ctx, refs=("HEAD",), states=states)
    if rep["result"] != "ok":
        return {"ok": False, "reason": f"snapshot_{rep['result']}", "snapshot": rep}
    in_head = tree_manifests(root, "HEAD") if head else {}
    wt = worktree_manifests(ctx)
    added = sorted(b for b, m in wt.items() if m is not None and b not in in_head)
    if require_complete:
        comp = completeness(ctx, None)
        if not comp["complete"]:
            return {"ok": False, "reason": "not_complete", "completeness": comp}
    if not added:
        return {"ok": True, "committed": False, "reason": "nothing_to_commit", "snapshot": rep}
    paths = []
    for b in added:
        base_abs = os.path.join(root, *b.rstrip("/").split("/"))
        for dirpath, _, fns in os.walk(base_abs):
            for fn in fns:
                paths.append(os.path.relpath(os.path.join(dirpath, fn), root).replace(os.sep, "/"))
    oids = gitops.hash_files(root, sorted(paths))
    msg = _message(task, title, rep["sessions"], rep["policy_version"], added)
    problems = rules.check_message(msg)
    if problems:
        return {"ok": False, "reason": "message_format", "detail": ",".join(problems)}
    commit, _ = gitops.build_commit(root, head, msg, add={p: ("100644", o) for p, o in oids.items()},
                                    state_dir=ctx.state_dir)
    changes = gitops.diff_tree(root, head, commit)
    files = gitops.tree_files(root, commit, SNAPSHOTS_REL)
    blob_cache = {}

    def blob(path):
        if path not in files:
            return None
        oid = files[path][1]
        if oid not in blob_cache:
            blob_cache.update(gitops.cat_blobs(root, [oid]))
        return blob_cache.get(oid)

    problems = rules.check_changes(changes, blob, allow_source=False)
    if problems:
        return {"ok": False, "reason": "log_commit_check_failed", "detail": ",".join(problems)}
    try:
        gitops.cas_update_branch(root, branch, commit, head, "log snapshot commit")
    except GitError:
        return {"ok": False, "reason": "head_changed_during_commit"}
    gitops.sync_index_paths(root, commit, sorted(paths))
    return {"ok": True, "committed": True, "commit": commit, "branch": branch, "snapshots": len(added),
            "sessions": len(rep["sessions"]), "files": len(paths), "missing": rep["missing"]}


def submit_snapshots(ctx: Context, task: str | None = None, title: str = "세션 로그 제출") -> dict:
    """사용자가 모든 AI 응답이 끝난 뒤 실행하는 제출: 턴 보호 확인 → 전체 스냅샷 → 로그 전용 커밋."""
    from . import config, turns

    task = task or config.task_for_branch(ctx)
    if not task:
        return {"ok": False, "reason": "task_id_required", "detail": "feature 브랜치가 아니면 작업 ID를 지정"}
    with turns.guard_lock(ctx, timeout=20):
        states = turns.effective_states(ctx)
        busy = {k: v["state"] for k, v in states.items() if v["state"] != "idle"}
        if busy:
            return {"ok": False, "reason": "ai_turn_not_idle", "sessions": busy}
        return commit_snapshots(ctx, task, title, states=states)

toolu_01CXhiQT13CJFyzzTTdpHPQf.content:
"""불변 스냅샷과 로그 전용 커밋.

경로: ai-logs/snapshots/<tool>/<session-id>/<policy-version>/L<원본 바이트 20자리>-<sha256 앞 16자리>/
  manifest.json  + files/<원본 상대 경로>  (세션의 모든 파일 전체 사본, 마스킹만 적용)

- 같은 원본·같은 정책이면 같은 ID(폴더 이름)가 나온다. 생성 시각 같은 가변 값은 manifest에 넣지 않는다.
- 전체 sha256은 manifest의 snapshot_sha256에 기록한다(폴더 이름에는 앞 16자리만).
- 이미 있는 폴더는 고치지 않는다. 같은 ID인데 내용이 다르면 보류한다.
- 원본 길이가 같은데 내용(해시)이 다른 스냅샷은 '더 최신'으로 추정하지 않고 보류한다.
- 원본 앞부분 불변성(절단·재작성·삭제)은 이전 스냅샷·live·상태 기록 모두와 대조한다.
"""
from __future__ import annotations

import json
import os

from .common import (
    LARGE_FILE_BYTES,
    SCHEMA_VERSION,
    SNAPSHOTS_REL,
    Context,
    GitError,
    atomic_write,
    dumps_json,
    file_lock,
    read_json_ro,
    sha256,
    utc_now,
)
from .discover import Session, resolve_targets

TIME_BASIS = "UTC - 도구가 기록한 ISO 8601 timestamp 값을 그대로 사용"
ORDER_BASIS = "파일 안의 줄 순서 (타임스탬프로 재정렬하지 않음)"


# ------------------------------------------------------------------ identity
def _id_payload(m: dict) -> bytes:
    files = sorted(
        [e["path"], e["original_bytes"], e["original_sha256"], e["copy_sha256"]] for e in m.get("files", [])
    )
    payload = {
        "schema": m.get("schema"),
        "tool": m.get("tool"),
        "session_id": m.get("session_id"),
        "policy_version": m.get("policy_version"),
        "files": files,
    }
    return json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")


def snapshot_sha256(m: dict) -> str:
    return sha256(_id_payload(m))


def snapshot_id(m: dict) -> str:
    """manifest 내용으로 ID를 다시 계산한다(경로를 믿지 않는다)."""
    total = sum(int(e["original_bytes"]) for e in m.get("files", []))
    return "L%020d-%s" % (total, snapshot_sha256(m)[:16])


def snap_base(tool: str, sid: str, policy: str, sid_: str) -> str:
    return f"{SNAPSHOTS_REL}/{tool}/{sid}/{policy}/{sid_}/"


# ------------------------------------------------------------ known snapshots
def worktree_manifests(ctx: Context) -> dict[str, dict]:
    """작업 폴더의 스냅샷 manifest {base 경로: manifest}. 읽을 수 없는 manifest는 base만 표시(None)."""
    out: dict[str, dict] = {}
    root = ctx.snapshots_dir
    if not os.path.isdir(root):
        return out
    for tool in sorted(os.listdir(root)):
        for sid in sorted(_dirs(os.path.join(root, tool))):
            for pol in sorted(_dirs(os.path.join(root, tool, sid))):
                for snap in sorted(_dirs(os.path.join(root, tool, sid, pol))):
                    m, st = read_json_ro(os.path.join(root, tool, sid, pol, snap, "manifest.json"))
                    out[snap_base(tool, sid, pol, snap)] = m if st == "ok" and isinstance(m, dict) else None
    return out


def _dirs(path: str) -> list[str]:
    try:
        return [d for d in os.listdir(path) if os.path.isdir(os.path.join(path, d))]
    except OSError:
        return []


def tree_manifests(root: str, treeish: str) -> dict[str, dict]:
    """커밋 트리 안의 스냅샷 manifest {base 경로: manifest}(Git blob에서 읽음)."""
    from . import gitops

    files = gitops.tree_files(root, treeish, SNAPSHOTS_REL)
    mans = {p: oid for p, (_, oid) in files.items() if p.endswith("/manifest.json")}
    blobs = gitops.cat_blobs(root, mans.values())
    out = {}
    for path, oid in mans.items():
        base = path[: -len("manifest.json")]
        try:
            out[base] = json.loads(blobs[oid].decode("utf-8"))
        except (KeyError, ValueError, UnicodeDecodeError):
            out[base] = None
    return out


def known_manifests(ctx: Context, refs=()) -> dict[str, dict]:
    """작업 폴더 + 주어진 커밋들의 스냅샷 manifest 합집합."""
    out = {}
    for ref in refs:
        try:
            out.update({k: v for k, v in tree_manifests(ctx.root, ref).items() if k not in out or out[k] is None})
        except GitError:
            continue
    for k, v in worktree_manifests(ctx).items():
        if k not in out or out[k] is None:
            out[k] = v
    return out


def by_session(manifests: dict[str, dict]) -> dict[str, list[tuple[str, dict]]]:
    out: dict[str, list] = {}
    for base, m in manifests.items():
        parts = base.rstrip("/").split("/")
        out.setdefault(f"{parts[-4]}/{parts[-3]}", []).append((base, m))
    return out


def latest(entries: list[tuple[str, dict]], policy_version: str):
    """정책별 최신 스냅샷: 원본 바이트가 가장 큰 것. 같은 길이에 다른 ID가 있으면 (None, 'ambiguous')."""
    cands = [(b, m) for b, m in entries if m and m.get("policy_version") == policy_version]
    if not cands:
        return None, "none"
    top = max(m.get("original_bytes_total", -1) for _, m in cands)
    tops = {m.get("snapshot_id") for _, m in cands if m.get("original_bytes_total") == top}
    if len(tops) > 1:
        return None, "ambiguous"
    return next((b, m) for b, m in cands if m.get("original_bytes_total") == top), "ok"


# ------------------------------------------------------------------- create
def _prefix_problems(rel: str, data: bytes, prior: list[tuple[int, str]]) -> list[str]:
    out = []
    for n, h in sorted(set(prior)):
        if len(data) < n:
            out.append("original_truncated")
        elif sha256(data[:n]) != h:
            out.append("original_rewritten")
    return sorted(set(out))


def _prior_knowledge(session_key: str, state: dict, snaps: list[tuple[str, dict]]) -> dict[str, list]:
    """파일별 (원본 바이트, 앞부분 sha256) 기록: 상태(live 수집) + 모든 이전 스냅샷."""
    prior: dict[str, list] = {}
    prefix = session_key + "/"
    for k, v in (state.get("files") or {}).items():
        if k.startswith(prefix) and isinstance(v.get("original_bytes"), int) and v.get("original_sha256"):
            prior.setdefault(k[len(prefix):], []).append((v["original_bytes"], v["original_sha256"]))
    for _, m in snaps:
        for e in (m or {}).get("files", []):
            if isinstance(e.get("original_bytes"), int) and e.get("original_sha256"):
                prior.setdefault(e["path"], []).append((e["original_bytes"], e["original_sha256"]))
    return prior


def build_snapshot(ctx: Context, s: Session, policy, state: dict, snaps: list[tuple[str, dict]],
                   idle: bool) -> dict:
    """세션 하나의 스냅샷을 준비한다(쓰지 않음). 결과: {status: ready|hold, manifest, copies, problems, ...}.

    개행 없는 마지막 JSONL 기록: 세션이 idle로 확인되고 그 꼬리가 JSON으로 파싱되면 '종료된 유효 기록'으로
    포함한다. 그 밖에는 마지막 개행까지만 담고 deferred_tail로 보고한다(최종 완전성 검사는 실패한다).
    """
    from .engine import check_masked, jsonl_stats, read_full

    problems, warnings, deferred = [], [], []
    prior = _prior_knowledge(s.key, state, snaps)
    entries, copies = [], {}
    current = {f.rel for f in s.files}
    for rel in sorted(set(prior) - current):
        problems.append({"rule": "original_file_deleted", "file": rel})
    main_stats = (0, None, None)
    for f in s.files:
        try:
            data = read_full(f)
        except OSError as e:
            problems.append({"rule": "original_unreadable", "file": f.rel, "detail": type(e).__name__})
            continue
        ends_open = False
        if f.rel.endswith(".jsonl") and data and not data.endswith(b"\n"):
            cut = data.rfind(b"\n") + 1
            tail = data[cut:]
            try:
                json.loads(tail)
                tail_ok = True
            except ValueError:
                tail_ok = False
            if idle and tail_ok:
                ends_open = True
            else:
                deferred.append({"file": f.rel, "bytes": len(tail), "reason": "unterminated_tail"})
                data = data[:cut]
        for rule in _prefix_problems(f.rel, data, prior.get(f.rel, [])):
            problems.append({"rule": rule, "file": f.rel})
        masked, counts = policy.mask(data)
        for p in check_masked(f.rel, data, masked, policy):
            problems.append(p)
        if len(data) > LARGE_FILE_BYTES:
            warnings.append({"rule": "large_file", "file": f.rel, "detail": f"bytes={len(data)}"})
        entry = {
            "path": f.rel,
            "role": f.role,
            "original_bytes": len(data),
            "original_sha256": sha256(data),
            "copy_bytes": len(masked),
            "copy_sha256": sha256(masked),
            "masked": dict(sorted(counts.items())),
        }
        if f.rel.endswith(".jsonl"):
            n, first, last, bad = jsonl_stats(data)
            entry["lines"] = n
            entry["ends_without_newline"] = ends_open
            if bad:
                entry["non_json_lines"] = bad[:50]
            if f.role == "main":
                main_stats = (n, first, last)
        entries.append(entry)
        copies[f.rel] = masked
    entries.sort(key=lambda e: (e["role"] != "main", e["path"]))
    n, first, last = main_stats
    m = {
        "schema": SCHEMA_VERSION,
        "kind": "snapshot",
        "tool": s.tool,
        "session_id": s.session_id,
        "policy_version": policy.version,
        "time_basis": TIME_BASIS,
        "order_basis": ORDER_BASIS,
        "first_timestamp": first,
        "last_timestamp": last,
        "main_lines": n,
        "original_bytes_total": sum(e["original_bytes"] for e in entries),
        "files": entries,
        "warnings": warnings,
    }
    m["snapshot_sha256"] = snapshot_sha256(m)
    m["snapshot_id"] = snapshot_id(m)
    # 같은 정책에서 같은 길이·다른 내용, 또는 더 긴 스냅샷이 이미 있는데 지금이 더 짧은 경우
    for base, old in snaps:
        if not old or old.get("policy_version") != policy.version:
            continue
        if old.get("original_bytes_total") == m["original_bytes_total"] and old.get("snapshot_id") != m["snapshot_id"]:
            problems.append({"rule": "same_length_different_snapshot", "detail": base})
    status = "hold" if problems else "ready"
    return {"key": s.key, "status": status, "manifest": m, "copies": copies, "problems": problems,
            "warnings": warnings, "deferred": deferred,
            "base": snap_base(s.tool, s.session_id, policy.version, m["snapshot_id"])}


def write_snapshot(ctx: Context, prep: dict) -> str:
    """준비된 스냅샷을 쓴다. 이미 있으면 내용이 같은지 확인만 한다. 반환: created|exists|conflict."""
    base_abs = os.path.join(ctx.root, *prep["base"].rstrip("/").split("/"))
    mpath = os.path.join(base_abs, "manifest.json")
    want = dumps_json(prep["manifest"])
    if os.path.exists(mpath):
        with open(mpath, "rb") as f:
            have = f.read()
        if have != want:
            return "conflict"
        for rel, data in prep["copies"].items():
            p = os.path.join(base_abs, "files", *rel.split("/"))
            try:
                with open(p, "rb") as f:
                    if f.read() != data:
                        return "conflict"
            except FileNotFoundError:
                return "conflict"
        return "exists"
    for rel, data in prep["copies"].items():
        atomic_write(os.path.join(base_abs, "files", *rel.split("/")), data)
    atomic_write(mpath, want)  # manifest를 마지막에 써서 '완성된 폴더'의 표시로 삼는다
    return "created"


def snapshot_all(ctx: Context, refs=("HEAD",), states: dict | None = None) -> dict:
    """대상 세션 전체 스냅샷. 보류가 하나라도 있으면 그 세션은 쓰지 않는다."""
    from .engine import build_policy, load_state

    with file_lock(ctx.lock_path, timeout=60):
        state = load_state(ctx)
        policy = build_policy(ctx)
        known = known_manifests(ctx, refs)
        grouped = by_session(known)
        targets = resolve_targets(ctx, state, extra_known=grouped.keys())
        report = {"time": utc_now(), "policy_version": policy.version, "sessions": [], "holds": [],
                  "warnings": [], "missing": [], "result": "ok"}
        if not os.path.exists(ctx.mask_path):
            report.update(result="error", error="mask_list_missing")
            return report
        for s in targets.sessions:
            idle = bool(states and states.get(s.key, {}).get("state") == "idle")
            prep = build_snapshot(ctx, s, policy, state, grouped.get(s.key, []), idle)
            row = {"key": s.key, "base": prep["base"], "status": prep["status"],
                   "original_bytes": prep["manifest"]["original_bytes_total"],
                   "main_lines": prep["manifest"]["main_lines"],
                   "last_timestamp": prep["manifest"]["last_timestamp"]}
            if prep["deferred"]:
                row["deferred"] = prep["deferred"]
            if prep["status"] == "ready":
                row["status"] = write_snapshot(ctx, prep)
                if row["status"] == "conflict":
                    report["holds"].append({"rule": "snapshot_dir_conflict", "session": s.key})
            else:
                report["holds"].extend(dict(p, session=s.key) for p in prep["problems"])
            report["warnings"].extend(dict(w, session=s.key) for w in prep["warnings"])
            report["sessions"].append(row)
        for key in targets.missing:
            has = bool(grouped.get(key))
            report["missing"].append({"session": key, "snapshot_kept": has})
        if report["holds"]:
            report["result"] = "hold"
        return report


# ------------------------------------------------------------- completeness
def completeness(ctx: Context, treeish: str | None, policy=None, read_originals: bool = True) -> dict:
    """커밋(또는 작업 폴더) 기준 제출 완전성.

    모든 대상 세션에 대해, 현재 정책의 최신 스냅샷이 원본 파일 전체(EOF)와 같은지 확인한다.
    failures가 비어 있어야 '완전'이다. 원본이 사라진 세션은 이전 스냅샷이 있으면 경고, 없으면 실패.
    """
    from .engine import build_policy, load_state

    policy = policy or build_policy(ctx)
    mans = tree_manifests(ctx.root, treeish) if treeish else worktree_manifests(ctx)
    grouped = by_session(mans)
    state = load_state(ctx)
    targets = resolve_targets(ctx, state, extra_known=grouped.keys())
    failures, warnings, rows = [], [], []
    for base, m in mans.items():
        if m is None:
            failures.append({"rule": "snapshot_manifest_unreadable", "detail": base})
    for s in targets.sessions:
        b, how = latest(grouped.get(s.key, []), policy.version)
        if b is None:
            failures.append({"rule": "snapshot_missing" if how == "none" else "snapshot_ambiguous", "session": s.key})
            continue
        m = mans[b]
        listed = {e["path"]: e for e in m["files"]}
        cur = {f.rel: f for f in s.files}
        for rel in sorted(set(cur) - set(listed)):
            failures.append({"rule": "file_not_in_snapshot", "session": s.key, "file": rel})
        if read_originals:
            for rel, e in listed.items():
                f = cur.get(rel)
                if f is None:
                    failures.append({"rule": "original_file_deleted", "session": s.key, "file": rel})
                    continue
                try:
                    size = os.path.getsize(f.path)
                    with open(f.path, "rb") as fh:
                        head = fh.read(e["original_bytes"])
                except OSError:
                    failures.append({"rule": "original_unreadable", "session": s.key, "file": rel})
                    continue
                if size < e["original_bytes"] or sha256(head) != e["original_sha256"]:
                    failures.append({"rule": "original_changed", "session": s.key, "file": rel})
                elif size > e["original_bytes"]:
                    failures.append({"rule": "snapshot_behind_original", "session": s.key, "file": rel,
                                     "detail": f"bytes={size - e['original_bytes']}"})
        rows.append({"key": s.key, "snapshot": b, "original_bytes": m.get("original_bytes_total")})
    for key in targets.missing:
        if grouped.get(key):
            warnings.append({"rule": "original_missing_snapshot_kept", "session": key})
        else:
            failures.append({"rule": "original_missing_not_snapshotted", "session": key})
    if targets.unresolved:
        warnings.append({"rule": "unresolved_codex_files", "detail": f"count={targets.unresolved}"})
    return {"treeish": treeish or "worktree", "policy_version": policy.version, "sessions": rows,
            "failures": failures, "warnings": warnings, "complete": not failures}


def scan_tree_secrets(ctx: Context, treeish: str, policy=None) -> list[dict]:
    """커밋 트리의 모든 스냅샷 blob을 현재 정책으로 다시 검사한다(치환 목록 잔류·민감정보 후보).

    이미 커밋된 값은 새 마스킹 커밋으로 지워지지 않는다. 발견되면 게시를 멈추고 보고한다.
    """
    from . import gitops
    from .engine import build_policy

    policy = policy or build_policy(ctx)
    files = gitops.tree_files(ctx.root, treeish, SNAPSHOTS_REL)
    blobs = gitops.cat_blobs(ctx.root, {oid for p, (_, oid) in files.items() if "/files/" in p})
    out = []
    for path, (_, oid) in sorted(files.items()):
        if "/files/" not in path:
            continue
        data = blobs.get(oid, b"")
        if policy.residue(data):
            out.append({"rule": "committed_mask_residue", "file": path})
        for h in policy.detect(data):
            out.append({"rule": "committed_" + h.rule, "file": path, "line": h.line})
    return out


# ------------------------------------------------------------ live coverage
def live_covered(ctx: Context) -> dict:
    """live 사본 ⊆ 스냅샷: live 제외 정책으로 바꾸기 전 확인.

    각 live 파일에 대해 같은 세션의 최신 스냅샷(정책 무관, 원본 바이트 최대)이 live보다 길거나 같고,
    현재 원본 기준으로 두 범위가 모두 같은 원본의 앞부분이며, 같은 정책이면 스냅샷 사본이 live 사본으로 시작한다.
    """
    import glob

    snaps = by_session(worktree_manifests(ctx))
    gaps, checked = [], 0
    for mpath in glob.glob(os.path.join(ctx.live_dir, "*", "*", "manifest.json")):
        m, st = read_json_ro(mpath)
        if st != "ok":
            gaps.append({"rule": "live_manifest_unreadable", "detail": os.path.basename(os.path.dirname(mpath))})
            continue
        key = f"{m['tool']}/{m['session_id']}"
        cands = [x for x in snaps.get(key, []) if x[1]]
        for e in m["files"]:
            checked += 1
            best = None
            for base, sm in cands:
                se = next((x for x in sm["files"] if x["path"] == e["path"]), None)
                if se and se["original_bytes"] >= e["original_bytes"]:
                    if best is None or se["original_bytes"] > best[1]["original_bytes"]:
                        best = (base, se, sm)
            if best is None:
                gaps.append({"rule": "live_not_in_snapshot", "session": key, "file": e["path"]})
                continue
            base, se, sm = best
            live_copy = os.path.join(os.path.dirname(mpath), "files", *e["path"].split("/"))
            snap_copy = os.path.join(ctx.root, *base.rstrip("/").split("/"), "files", *e["path"].split("/"))
            if sm.get("policy_version") == m.get("policy_version"):
                with open(live_copy, "rb") as a, open(snap_copy, "rb") as b:
                    if not b.read().startswith(a.read()):
                        gaps.append({"rule": "snapshot_not_extending_live", "session": key, "file": e["path"]})
            # 정책이 다르면 원본 기준으로 대조: live 범위와 스냅샷 범위가 같은 원본의 앞부분이어야 한다
            orig = _original_path(ctx, key, e["path"])
            if orig:
                with open(orig, "rb") as f:
                    data = f.read(se["original_bytes"])
                if sha256(data[: e["original_bytes"]]) != e["original_sha256"] or sha256(data) != se["original_sha256"]:
                    gaps.append({"rule": "live_snapshot_original_mismatch", "session": key, "file": e["path"]})
            elif sm.get("policy_version") != m.get("policy_version"):
                gaps.append({"rule": "original_missing_cannot_compare", "session": key, "file": e["path"]})
    return {"files_checked": checked, "gaps": gaps, "covered": not gaps}


def _original_path(ctx: Context, key: str, rel: str):
    from .engine import load_state

    targets = resolve_targets(ctx, load_state(ctx))
    for s in targets.sessions:
        if s.key == key:
            for f in s.files:
                if f.rel == rel:
                    return f.path
    return None


# ---------------------------------------------------------------- commit
def _message(task: str, title: str, rows: list[dict], policy_version: str, added: list[str]) -> str:
    body = [f"  스냅샷 {len(added)}개 추가 (정책 {policy_version}, 세션 {len(rows)}개 확인)"]
    for r in rows:
        if r["base"] in added:
            body.append(f"  - {r['key']}: {r['base'].rstrip('/').split('/')[-1]}, {r['main_lines']}줄, "
                        f"마지막 {r['last_timestamp']}")
    return f"[{task}] {title}\n\n" + "\n".join(body) + "\n"


def commit_snapshots(ctx: Context, task: str, title: str, *, expect_branch: str | None = None,
                     expect_head: str | None = None, states: dict | None = None, require_complete: bool = False) -> dict:
    """현재 브랜치에 로그 전용 커밋(부모 1개)을 만든다. 사용자 index·작업 폴더의 다른 항목은 바꾸지 않는다.

    보류 조건: 분리된 HEAD, 진행 중인 Git 작업, 스테이징된 변경, 예상과 다른 브랜치·HEAD.
    변경할 스냅샷이 없으면 커밋하지 않는다(빈 커밋 금지).
    """
    from . import gitops, rules

    root = ctx.root
    branch = gitops.current_branch(root)
    head = gitops.rev(root, "HEAD")
    if not branch:
        return {"ok": False, "reason": "detached_head"}
    if expect_branch and branch != expect_branch:
        return {"ok": False, "reason": "branch_changed", "detail": f"{expect_branch}->{branch}"}
    if expect_head and head != expect_head:
        return {"ok": False, "reason": "head_changed"}
    busy = gitops.in_progress(root)
    if busy:
        return {"ok": False, "reason": "git_operation_in_progress", "detail": ",".join(busy)}
    if gitops.staged_changes(root):
        return {"ok": False, "reason": "staged_changes_present"}
    if not rules.TASK_ID_RE.match(task or ""):
        return {"ok": False, "reason": "task_id_format", "detail": "예: AI-LOG-001"}
    rep = snapshot_all(ctx, refs=("HEAD",), states=states)
    if rep["result"] != "ok":
        return {"ok": False, "reason": f"snapshot_{rep['result']}", "snapshot": rep}
    in_head = tree_manifests(root, "HEAD") if head else {}
    wt = worktree_manifests(ctx)
    added = sorted(b for b, m in wt.items() if m is not None and b not in in_head)
    if require_complete:
        comp = completeness(ctx, None)
        if not comp["complete"]:
            return {"ok": False, "reason": "not_complete", "completeness": comp}
    if not added:
        return {"ok": True, "committed": False, "reason": "nothing_to_commit", "snapshot": rep}
    paths = []
    for b in added:
        base_abs = os.path.join(root, *b.rstrip("/").split("/"))
        for dirpath, _, fns in os.walk(base_abs):
            for fn in fns:
                paths.append(os.path.relpath(os.path.join(dirpath, fn), root).replace(os.sep, "/"))
    oids = gitops.hash_files(root, sorted(paths))
    msg = _message(task, title, rep["sessions"], rep["policy_version"], added)
    problems = rules.check_message(msg)
    if problems:
        return {"ok": False, "reason": "message_format", "detail": ",".join(problems)}
    commit, _ = gitops.build_commit(root, head, msg, add={p: ("100644", o) for p, o in oids.items()},
                                    state_dir=ctx.state_dir)
    changes = gitops.diff_tree(root, head, commit)
    files = gitops.tree_files(root, commit, SNAPSHOTS_REL)
    blob_cache = {}

    def blob(path):
        if path not in files:
            return None
        oid = files[path][1]
        if oid not in blob_cache:
            blob_cache.update(gitops.cat_blobs(root, [oid]))
        return blob_cache.get(oid)

    problems = rules.check_changes(changes, blob, allow_source=False)
    if problems:
        return {"ok": False, "reason": "log_commit_check_failed", "detail": ",".join(problems)}
    try:
        gitops.cas_update_branch(root, branch, commit, head, "log snapshot commit")
    except GitError:
        return {"ok": False, "reason": "head_changed_during_commit"}
    gitops.sync_index_paths(root, commit, sorted(paths))
    return {"ok": True, "committed": True, "commit": commit, "branch": branch, "snapshots": len(added),
            "sessions": len(rep["sessions"]), "files": len(paths), "missing": rep["missing"]}


def submit_snapshots(ctx: Context, task: str | None = None, title: str = "세션 로그 제출") -> dict:
    """사용자가 모든 AI 응답이 끝난 뒤 실행하는 제출: 턴 보호 확인 → 전체 스냅샷 → 로그 전용 커밋."""
    from . import config, turns

    task = task or config.task_for_branch(ctx)
    if not task:
        return {"ok": False, "reason": "task_id_required", "detail": "feature 브랜치가 아니면 작업 ID를 지정"}
    with turns.guard_lock(ctx, timeout=20):
        states = turns.effective_states(ctx)
        busy = {k: v["state"] for k, v in states.items() if v["state"] != "idle"}
        if busy:
            return {"ok": False, "reason": "ai_turn_not_idle", "sessions": busy}
        return commit_snapshots(ctx, task, title, states=states)

toolUseResult.content:
"""불변 스냅샷과 로그 전용 커밋.

경로: ai-logs/snapshots/<tool>/<session-id>/<policy-version>/L<원본 바이트 20자리>-<sha256 앞 16자리>/
  manifest.json  + files/<원본 상대 경로>  (세션의 모든 파일 전체 사본, 마스킹만 적용)

- 같은 원본·같은 정책이면 같은 ID(폴더 이름)가 나온다. 생성 시각 같은 가변 값은 manifest에 넣지 않는다.
- 전체 sha256은 manifest의 snapshot_sha256에 기록한다(폴더 이름에는 앞 16자리만).
- 이미 있는 폴더는 고치지 않는다. 같은 ID인데 내용이 다르면 보류한다.
- 원본 길이가 같은데 내용(해시)이 다른 스냅샷은 '더 최신'으로 추정하지 않고 보류한다.
- 원본 앞부분 불변성(절단·재작성·삭제)은 이전 스냅샷·live·상태 기록 모두와 대조한다.
"""
from __future__ import annotations

import json
import os

from .common import (
    LARGE_FILE_BYTES,
    SCHEMA_VERSION,
    SNAPSHOTS_REL,
    Context,
    GitError,
    atomic_write,
    dumps_json,
    file_lock,
    read_json_ro,
    sha256,
    utc_now,
)
from .discover import Session, resolve_targets

TIME_BASIS = "UTC - 도구가 기록한 ISO 8601 timestamp 값을 그대로 사용"
ORDER_BASIS = "파일 안의 줄 순서 (타임스탬프로 재정렬하지 않음)"


# ------------------------------------------------------------------ identity
def _id_payload(m: dict) -> bytes:
    files = sorted(
        [e["path"], e["original_bytes"], e["original_sha256"], e["copy_sha256"]] for e in m.get("files", [])
    )
    payload = {
        "schema": m.get("schema"),
        "tool": m.get("tool"),
        "session_id": m.get("session_id"),
        "policy_version": m.get("policy_version"),
        "files": files,
    }
    return json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")


def snapshot_sha256(m: dict) -> str:
    return sha256(_id_payload(m))


def snapshot_id(m: dict) -> str:
    """manifest 내용으로 ID를 다시 계산한다(경로를 믿지 않는다)."""
    total = sum(int(e["original_bytes"]) for e in m.get("files", []))
    return "L%020d-%s" % (total, snapshot_sha256(m)[:16])


def snap_base(tool: str, sid: str, policy: str, sid_: str) -> str:
    return f"{SNAPSHOTS_REL}/{tool}/{sid}/{policy}/{sid_}/"


# ------------------------------------------------------------ known snapshots
def worktree_manifests(ctx: Context) -> dict[str, dict]:
    """작업 폴더의 스냅샷 manifest {base 경로: manifest}. 읽을 수 없는 manifest는 base만 표시(None)."""
    out: dict[str, dict] = {}
    root = ctx.snapshots_dir
    if not os.path.isdir(root):
        return out
    for tool in sorted(os.listdir(root)):
        for sid in sorted(_dirs(os.path.join(root, tool))):
            for pol in sorted(_dirs(os.path.join(root, tool, sid))):
                for snap in sorted(_dirs(os.path.join(root, tool, sid, pol))):
                    m, st = read_json_ro(os.path.join(root, tool, sid, pol, snap, "manifest.json"))
                    out[snap_base(tool, sid, pol, snap)] = m if st == "ok" and isinstance(m, dict) else None
    return out


def _dirs(path: str) -> list[str]:
    try:
        return [d for d in os.listdir(path) if os.path.isdir(os.path.join(path, d))]
    except OSError:
        return []


def tree_manifests(root: str, treeish: str) -> dict[str, dict]:
    """커밋 트리 안의 스냅샷 manifest {base 경로: manifest}(Git blob에서 읽음)."""
    from . import gitops

    files = gitops.tree_files(root, treeish, SNAPSHOTS_REL)
    mans = {p: oid for p, (_, oid) in files.items() if p.endswith("/manifest.json")}
    blobs = gitops.cat_blobs(root, mans.values())
    out = {}
    for path, oid in mans.items():
        base = path[: -len("manifest.json")]
        try:
            out[base] = json.loads(blobs[oid].decode("utf-8"))
        except (KeyError, ValueError, UnicodeDecodeError):
            out[base] = None
    return out


def known_manifests(ctx: Context, refs=()) -> dict[str, dict]:
    """작업 폴더 + 주어진 커밋들의 스냅샷 manifest 합집합."""
    out = {}
    for ref in refs:
        try:
            out.update({k: v for k, v in tree_manifests(ctx.root, ref).items() if k not in out or out[k] is None})
        except GitError:
            continue
    for k, v in worktree_manifests(ctx).items():
        if k not in out or out[k] is None:
            out[k] = v
    return out


def by_session(manifests: dict[str, dict]) -> dict[str, list[tuple[str, dict]]]:
    out: dict[str, list] = {}
    for base, m in manifests.items():
        parts = base.rstrip("/").split("/")
        out.setdefault(f"{parts[-4]}/{parts[-3]}", []).append((base, m))
    return out


def latest(entries: list[tuple[str, dict]], policy_version: str):
    """정책별 최신 스냅샷: 원본 바이트가 가장 큰 것. 같은 길이에 다른 ID가 있으면 (None, 'ambiguous')."""
    cands = [(b, m) for b, m in entries if m and m.get("policy_version") == policy_version]
    if not cands:
        return None, "none"
    top = max(m.get("original_bytes_total", -1) for _, m in cands)
    tops = {m.get("snapshot_id") for _, m in cands if m.get("original_bytes_total") == top}
    if len(tops) > 1:
        return None, "ambiguous"
    return next((b, m) for b, m in cands if m.get("original_bytes_total") == top), "ok"


# ------------------------------------------------------------------- create
def _prefix_problems(rel: str, data: bytes, prior: list[tuple[int, str]]) -> list[str]:
    out = []
    for n, h in sorted(set(prior)):
        if len(data) < n:
            out.append("original_truncated")
        elif sha256(data[:n]) != h:
            out.append("original_rewritten")
    return sorted(set(out))


def _prior_knowledge(session_key: str, state: dict, snaps: list[tuple[str, dict]]) -> dict[str, list]:
    """파일별 (원본 바이트, 앞부분 sha256) 기록: 상태(live 수집) + 모든 이전 스냅샷."""
    prior: dict[str, list] = {}
    prefix = session_key + "/"
    for k, v in (state.get("files") or {}).items():
        if k.startswith(prefix) and isinstance(v.get("original_bytes"), int) and v.get("original_sha256"):
            prior.setdefault(k[len(prefix):], []).append((v["original_bytes"], v["original_sha256"]))
    for _, m in snaps:
        for e in (m or {}).get("files", []):
            if isinstance(e.get("original_bytes"), int) and e.get("original_sha256"):
                prior.setdefault(e["path"], []).append((e["original_bytes"], e["original_sha256"]))
    return prior


def build_snapshot(ctx: Context, s: Session, policy, state: dict, snaps: list[tuple[str, dict]],
                   idle: bool) -> dict:
    """세션 하나의 스냅샷을 준비한다(쓰지 않음). 결과: {status: ready|hold, manifest, copies, problems, ...}.

    개행 없는 마지막 JSONL 기록: 세션이 idle로 확인되고 그 꼬리가 JSON으로 파싱되면 '종료된 유효 기록'으로
    포함한다. 그 밖에는 마지막 개행까지만 담고 deferred_tail로 보고한다(최종 완전성 검사는 실패한다).
    """
    from .engine import check_masked, jsonl_stats, read_full

    problems, warnings, deferred = [], [], []
    prior = _prior_knowledge(s.key, state, snaps)
    entries, copies = [], {}
    current = {f.rel for f in s.files}
    for rel in sorted(set(prior) - current):
        problems.append({"rule": "original_file_deleted", "file": rel})
    main_stats = (0, None, None)
    for f in s.files:
        try:
            data = read_full(f)
        except OSError as e:
            problems.append({"rule": "original_unreadable", "file": f.rel, "detail": type(e).__name__})
            continue
        ends_open = False
        if f.rel.endswith(".jsonl") and data and not data.endswith(b"\n"):
            cut = data.rfind(b"\n") + 1
            tail = data[cut:]
            try:
                json.loads(tail)
                tail_ok = True
            except ValueError:
                tail_ok = False
            if idle and tail_ok:
                ends_open = True
            else:
                deferred.append({"file": f.rel, "bytes": len(tail), "reason": "unterminated_tail"})
                data = data[:cut]
        for rule in _prefix_problems(f.rel, data, prior.get(f.rel, [])):
            problems.append({"rule": rule, "file": f.rel})
        masked, counts = policy.mask(data)
        for p in check_masked(f.rel, data, masked, policy):
            problems.append(p)
        if len(data) > LARGE_FILE_BYTES:
            warnings.append({"rule": "large_file", "file": f.rel, "detail": f"bytes={len(data)}"})
        entry = {
            "path": f.rel,
            "role": f.role,
            "original_bytes": len(data),
            "original_sha256": sha256(data),
            "copy_bytes": len(masked),
            "copy_sha256": sha256(masked),
            "masked": dict(sorted(counts.items())),
        }
        if f.rel.endswith(".jsonl"):
            n, first, last, bad = jsonl_stats(data)
            entry["lines"] = n
            entry["ends_without_newline"] = ends_open
            if bad:
                entry["non_json_lines"] = bad[:50]
            if f.role == "main":
                main_stats = (n, first, last)
        entries.append(entry)
        copies[f.rel] = masked
    entries.sort(key=lambda e: (e["role"] != "main", e["path"]))
    n, first, last = main_stats
    m = {
        "schema": SCHEMA_VERSION,
        "kind": "snapshot",
        "tool": s.tool,
        "session_id": s.session_id,
        "policy_version": policy.version,
        "time_basis": TIME_BASIS,
        "order_basis": ORDER_BASIS,
        "first_timestamp": first,
        "last_timestamp": last,
        "main_lines": n,
        "original_bytes_total": sum(e["original_bytes"] for e in entries),
        "files": entries,
        "warnings": warnings,
    }
    m["snapshot_sha256"] = snapshot_sha256(m)
    m["snapshot_id"] = snapshot_id(m)
    # 같은 정책에서 같은 길이·다른 내용, 또는 더 긴 스냅샷이 이미 있는데 지금이 더 짧은 경우
    for base, old in snaps:
        if not old or old.get("policy_version") != policy.version:
            continue
        if old.get("original_bytes_total") == m["original_bytes_total"] and old.get("snapshot_id") != m["snapshot_id"]:
            problems.append({"rule": "same_length_different_snapshot", "detail": base})
    status = "hold" if problems else "ready"
    return {"key": s.key, "status": status, "manifest": m, "copies": copies, "problems": problems,
            "warnings": warnings, "deferred": deferred,
            "base": snap_base(s.tool, s.session_id, policy.version, m["snapshot_id"])}


def write_snapshot(ctx: Context, prep: dict) -> str:
    """준비된 스냅샷을 쓴다. 이미 있으면 내용이 같은지 확인만 한다. 반환: created|exists|conflict."""
    base_abs = os.path.join(ctx.root, *prep["base"].rstrip("/").split("/"))
    mpath = os.path.join(base_abs, "manifest.json")
    want = dumps_json(prep["manifest"])
    if os.path.exists(mpath):
        with open(mpath, "rb") as f:
            have = f.read()
        if have != want:
            return "conflict"
        for rel, data in prep["copies"].items():
            p = os.path.join(base_abs, "files", *rel.split("/"))
            try:
                with open(p, "rb") as f:
                    if f.read() != data:
                        return "conflict"
            except FileNotFoundError:
                return "conflict"
        return "exists"
    for rel, data in prep["copies"].items():
        atomic_write(os.path.join(base_abs, "files", *rel.split("/")), data)
    atomic_write(mpath, want)  # manifest를 마지막에 써서 '완성된 폴더'의 표시로 삼는다
    return "created"


def snapshot_all(ctx: Context, refs=("HEAD",), states: dict | None = None) -> dict:
    """대상 세션 전체 스냅샷. 보류가 하나라도 있으면 그 세션은 쓰지 않는다."""
    from .engine import build_policy, load_state

    with file_lock(ctx.lock_path, timeout=60):
        state = load_state(ctx)
        policy = build_policy(ctx)
        known = known_manifests(ctx, refs)
        grouped = by_session(known)
        targets = resolve_targets(ctx, state, extra_known=grouped.keys())
        report = {"time": utc_now(), "policy_version": policy.version, "sessions": [], "holds": [],
                  "warnings": [], "missing": [], "result": "ok"}
        if not os.path.exists(ctx.mask_path):
            report.update(result="error", error="mask_list_missing")
            return report
        for s in targets.sessions:
            idle = bool(states and states.get(s.key, {}).get("state") == "idle")
            prep = build_snapshot(ctx, s, policy, state, grouped.get(s.key, []), idle)
            row = {"key": s.key, "base": prep["base"], "status": prep["status"],
                   "original_bytes": prep["manifest"]["original_bytes_total"],
                   "main_lines": prep["manifest"]["main_lines"],
                   "last_timestamp": prep["manifest"]["last_timestamp"]}
            if prep["deferred"]:
                row["deferred"] = prep["deferred"]
            if prep["status"] == "ready":
                row["status"] = write_snapshot(ctx, prep)
                if row["status"] == "conflict":
                    report["holds"].append({"rule": "snapshot_dir_conflict", "session": s.key})
            else:
                report["holds"].extend(dict(p, session=s.key) for p in prep["problems"])
            report["warnings"].extend(dict(w, session=s.key) for w in prep["warnings"])
            report["sessions"].append(row)
        for key in targets.missing:
            has = bool(grouped.get(key))
            report["missing"].append({"session": key, "snapshot_kept": has})
        if report["holds"]:
            report["result"] = "hold"
        return report


# ------------------------------------------------------------- completeness
def completeness(ctx: Context, treeish: str | None, policy=None, read_originals: bool = True) -> dict:
    """커밋(또는 작업 폴더) 기준 제출 완전성.

    모든 대상 세션에 대해, 현재 정책의 최신 스냅샷이 원본 파일 전체(EOF)와 같은지 확인한다.
    failures가 비어 있어야 '완전'이다. 원본이 사라진 세션은 이전 스냅샷이 있으면 경고, 없으면 실패.
    """
    from .engine import build_policy, load_state

    policy = policy or build_policy(ctx)
    mans = tree_manifests(ctx.root, treeish) if treeish else worktree_manifests(ctx)
    grouped = by_session(mans)
    state = load_state(ctx)
    targets = resolve_targets(ctx, state, extra_known=grouped.keys())
    failures, warnings, rows = [], [], []
    for base, m in mans.items():
        if m is None:
            failures.append({"rule": "snapshot_manifest_unreadable", "detail": base})
    for s in targets.sessions:
        b, how = latest(grouped.get(s.key, []), policy.version)
        if b is None:
            failures.append({"rule": "snapshot_missing" if how == "none" else "snapshot_ambiguous", "session": s.key})
            continue
        m = mans[b]
        listed = {e["path"]: e for e in m["files"]}
        cur = {f.rel: f for f in s.files}
        for rel in sorted(set(cur) - set(listed)):
            failures.append({"rule": "file_not_in_snapshot", "session": s.key, "file": rel})
        if read_originals:
            for rel, e in listed.items():
                f = cur.get(rel)
                if f is None:
                    failures.append({"rule": "original_file_deleted", "session": s.key, "file": rel})
                    continue
                try:
                    size = os.path.getsize(f.path)
                    with open(f.path, "rb") as fh:
                        head = fh.read(e["original_bytes"])
                except OSError:
                    failures.append({"rule": "original_unreadable", "session": s.key, "file": rel})
                    continue
                if size < e["original_bytes"] or sha256(head) != e["original_sha256"]:
                    failures.append({"rule": "original_changed", "session": s.key, "file": rel})
                elif size > e["original_bytes"]:
                    failures.append({"rule": "snapshot_behind_original", "session": s.key, "file": rel,
                                     "detail": f"bytes={size - e['original_bytes']}"})
        rows.append({"key": s.key, "snapshot": b, "original_bytes": m.get("original_bytes_total")})
    for key in targets.missing:
        if grouped.get(key):
            warnings.append({"rule": "original_missing_snapshot_kept", "session": key})
        else:
            failures.append({"rule": "original_missing_not_snapshotted", "session": key})
    if targets.unresolved:
        warnings.append({"rule": "unresolved_codex_files", "detail": f"count={targets.unresolved}"})
    return {"treeish": treeish or "worktree", "policy_version": policy.version, "sessions": rows,
            "failures": failures, "warnings": warnings, "complete": not failures}


def scan_tree_secrets(ctx: Context, treeish: str, policy=None) -> list[dict]:
    """커밋 트리의 모든 스냅샷 blob을 현재 정책으로 다시 검사한다(치환 목록 잔류·민감정보 후보).

    이미 커밋된 값은 새 마스킹 커밋으로 지워지지 않는다. 발견되면 게시를 멈추고 보고한다.
    """
    from . import gitops
    from .engine import build_policy

    policy = policy or build_policy(ctx)
    files = gitops.tree_files(ctx.root, treeish, SNAPSHOTS_REL)
    blobs = gitops.cat_blobs(ctx.root, {oid for p, (_, oid) in files.items() if "/files/" in p})
    out = []
    for path, (_, oid) in sorted(files.items()):
        if "/files/" not in path:
            continue
        data = blobs.get(oid, b"")
        if policy.residue(data):
            out.append({"rule": "committed_mask_residue", "file": path})
        for h in policy.detect(data):
            out.append({"rule": "committed_" + h.rule, "file": path, "line": h.line})
    return out


# ------------------------------------------------------------ live coverage
def live_covered(ctx: Context) -> dict:
    """live 사본 ⊆ 스냅샷: live 제외 정책으로 바꾸기 전 확인.

    각 live 파일에 대해 같은 세션의 최신 스냅샷(정책 무관, 원본 바이트 최대)이 live보다 길거나 같고,
    현재 원본 기준으로 두 범위가 모두 같은 원본의 앞부분이며, 같은 정책이면 스냅샷 사본이 live 사본으로 시작한다.
    """
    import glob

    snaps = by_session(worktree_manifests(ctx))
    gaps, checked = [], 0
    for mpath in glob.glob(os.path.join(ctx.live_dir, "*", "*", "manifest.json")):
        m, st = read_json_ro(mpath)
        if st != "ok":
            gaps.append({"rule": "live_manifest_unreadable", "detail": os.path.basename(os.path.dirname(mpath))})
            continue
        key = f"{m['tool']}/{m['session_id']}"
        cands = [x for x in snaps.get(key, []) if x[1]]
        for e in m["files"]:
            checked += 1
            best = None
            for base, sm in cands:
                se = next((x for x in sm["files"] if x["path"] == e["path"]), None)
                if se and se["original_bytes"] >= e["original_bytes"]:
                    if best is None or se["original_bytes"] > best[1]["original_bytes"]:
                        best = (base, se, sm)
            if best is None:
                gaps.append({"rule": "live_not_in_snapshot", "session": key, "file": e["path"]})
                continue
            base, se, sm = best
            live_copy = os.path.join(os.path.dirname(mpath), "files", *e["path"].split("/"))
            snap_copy = os.path.join(ctx.root, *base.rstrip("/").split("/"), "files", *e["path"].split("/"))
            if sm.get("policy_version") == m.get("policy_version"):
                with open(live_copy, "rb") as a, open(snap_copy, "rb") as b:
                    if not b.read().startswith(a.read()):
                        gaps.append({"rule": "snapshot_not_extending_live", "session": key, "file": e["path"]})
            # 정책이 다르면 원본 기준으로 대조: live 범위와 스냅샷 범위가 같은 원본의 앞부분이어야 한다
            orig = _original_path(ctx, key, e["path"])
            if orig:
                with open(orig, "rb") as f:
                    data = f.read(se["original_bytes"])
                if sha256(data[: e["original_bytes"]]) != e["original_sha256"] or sha256(data) != se["original_sha256"]:
                    gaps.append({"rule": "live_snapshot_original_mismatch", "session": key, "file": e["path"]})
            elif sm.get("policy_version") != m.get("policy_version"):
                gaps.append({"rule": "original_missing_cannot_compare", "session": key, "file": e["path"]})
    return {"files_checked": checked, "gaps": gaps, "covered": not gaps}


def _original_path(ctx: Context, key: str, rel: str):
    from .engine import load_state

    targets = resolve_targets(ctx, load_state(ctx))
    for s in targets.sessions:
        if s.key == key:
            for f in s.files:
                if f.rel == rel:
                    return f.path
    return None


# ---------------------------------------------------------------- commit
def _message(task: str, title: str, rows: list[dict], policy_version: str, added: list[str]) -> str:
    body = [f"  스냅샷 {len(added)}개 추가 (정책 {policy_version}, 세션 {len(rows)}개 확인)"]
    for r in rows:
        if r["base"] in added:
            body.append(f"  - {r['key']}: {r['base'].rstrip('/').split('/')[-1]}, {r['main_lines']}줄, "
                        f"마지막 {r['last_timestamp']}")
    return f"[{task}] {title}\n\n" + "\n".join(body) + "\n"


def commit_snapshots(ctx: Context, task: str, title: str, *, expect_branch: str | None = None,
                     expect_head: str | None = None, states: dict | None = None, require_complete: bool = False) -> dict:
    """현재 브랜치에 로그 전용 커밋(부모 1개)을 만든다. 사용자 index·작업 폴더의 다른 항목은 바꾸지 않는다.

    보류 조건: 분리된 HEAD, 진행 중인 Git 작업, 스테이징된 변경, 예상과 다른 브랜치·HEAD.
    변경할 스냅샷이 없으면 커밋하지 않는다(빈 커밋 금지).
    """
    from . import gitops, rules

    root = ctx.root
    branch = gitops.current_branch(root)
    head = gitops.rev(root, "HEAD")
    if not branch:
        return {"ok": False, "reason": "detached_head"}
    if expect_branch and branch != expect_branch:
        return {"ok": False, "reason": "branch_changed", "detail": f"{expect_branch}->{branch}"}
    if expect_head and head != expect_head:
        return {"ok": False, "reason": "head_changed"}
    busy = gitops.in_progress(root)
    if busy:
        return {"ok": False, "reason": "git_operation_in_progress", "detail": ",".join(busy)}
    if gitops.staged_changes(root):
        return {"ok": False, "reason": "staged_changes_present"}
    if not rules.TASK_ID_RE.match(task or ""):
        return {"ok": False, "reason": "task_id_format", "detail": "예: AI-LOG-001"}
    rep = snapshot_all(ctx, refs=("HEAD",), states=states)
    if rep["result"] != "ok":
        return {"ok": False, "reason": f"snapshot_{rep['result']}", "snapshot": rep}
    in_head = tree_manifests(root, "HEAD") if head else {}
    wt = worktree_manifests(ctx)
    added = sorted(b for b, m in wt.items() if m is not None and b not in in_head)
    if require_complete:
        comp = completeness(ctx, None)
        if not comp["complete"]:
            return {"ok": False, "reason": "not_complete", "completeness": comp}
    if not added:
        return {"ok": True, "committed": False, "reason": "nothing_to_commit", "snapshot": rep}
    paths = []
    for b in added:
        base_abs = os.path.join(root, *b.rstrip("/").split("/"))
        for dirpath, _, fns in os.walk(base_abs):
            for fn in fns:
                paths.append(os.path.relpath(os.path.join(dirpath, fn), root).replace(os.sep, "/"))
    oids = gitops.hash_files(root, sorted(paths))
    msg = _message(task, title, rep["sessions"], rep["policy_version"], added)
    problems = rules.check_message(msg)
    if problems:
        return {"ok": False, "reason": "message_format", "detail": ",".join(problems)}
    commit, _ = gitops.build_commit(root, head, msg, add={p: ("100644", o) for p, o in oids.items()},
                                    state_dir=ctx.state_dir)
    changes = gitops.diff_tree(root, head, commit)
    files = gitops.tree_files(root, commit, SNAPSHOTS_REL)
    blob_cache = {}

    def blob(path):
        if path not in files:
            return None
        oid = files[path][1]
        if oid not in blob_cache:
            blob_cache.update(gitops.cat_blobs(root, [oid]))
        return blob_cache.get(oid)

    problems = rules.check_changes(changes, blob, allow_source=False)
    if problems:
        return {"ok": False, "reason": "log_commit_check_failed", "detail": ",".join(problems)}
    try:
        gitops.cas_update_branch(root, branch, commit, head, "log snapshot commit")
    except GitError:
        return {"ok": False, "reason": "head_changed_during_commit"}
    gitops.sync_index_paths(root, commit, sorted(paths))
    return {"ok": True, "committed": True, "commit": commit, "branch": branch, "snapshots": len(added),
            "sessions": len(rep["sessions"]), "files": len(paths), "missing": rep["missing"]}


def submit_snapshots(ctx: Context, task: str | None = None, title: str = "세션 로그 제출") -> dict:
    """사용자가 모든 AI 응답이 끝난 뒤 실행하는 제출: 턴 보호 확인 → 전체 스냅샷 → 로그 전용 커밋."""
    from . import config, turns

    task = task or config.task_for_branch(ctx)
    if not task:
        return {"ok": False, "reason": "task_id_required", "detail": "feature 브랜치가 아니면 작업 ID를 지정"}
    with turns.guard_lock(ctx, timeout=20):
        states = turns.effective_states(ctx)
        busy = {k: v["state"] for k, v in states.items() if v["state"] != "idle"}
        if busy:
            return {"ok": False, "reason": "ai_turn_not_idle", "sessions": busy}
        return commit_snapshots(ctx, task, title, states=states)

input.content:
"""AI 턴 보호(turn guard).

세션별 상태: active(턴 진행 중) / idle(턴 종료 확인) / unknown(판단 불가).
- UserPromptSubmit: 보호 잠금 안에서 active + 세대(gen)를 기록한다. 기록하지 못하면 exit 2로 프롬프트를 막는다.
- Stop: 지금 턴의 Stop임이 확인될 때만 idle로 바꾼다.
  Codex는 turn_id가 같아야 한다. Claude는 last_assistant_message가 이 턴 시작 이후의 원본에 있어야 한다
  (원본 기록이 늦을 수 있어 잠시 다시 읽는다). 확인하지 못하면 바꾸지 않는다.
- SessionEnd·경과 시간·파일 크기 정지로 idle을 추정하지 않는다.
- 원본 증거: Claude system turn_duration·stop_hook_summary·중단 기록, Codex task_complete·turn_aborted.
  hook 기록과 원본 증거를 함께 본다. 증거가 이 턴 시작보다 뒤에 있을 때만 idle로 인정한다.
- 프롬프트 시작과 자동화 Git 작업은 같은 잠금(guard.lock)을 쓴다.
"""
from __future__ import annotations

import json
import os
import sys
import time
from contextlib import contextmanager

from .common import (
    Context,
    LockTimeout,
    append_jsonl,
    ensure_dir,
    file_lock,
    native_path,
    read_json_ro,
    sha256,
    utc_now,
    write_json,
)

ACTIVE, IDLE, UNKNOWN = "active", "idle", "unknown"
PROMPT_LOCK_TIMEOUT = 20.0
STOP_MATCH_WAIT = 3.0


class TurnStateError(Exception):
    pass


@contextmanager
def guard_lock(ctx: Context, timeout: float = PROMPT_LOCK_TIMEOUT):
    ensure_dir(ctx.state_dir)
    with file_lock(ctx.guard_lock_path, timeout=timeout):
        yield


def load_turns(ctx: Context) -> dict:
    data, status = read_json_ro(ctx.turns_path)
    if status == "missing":
        return {"schema": 1, "sessions": {}}
    if status != "ok" or not isinstance(data, dict) or not isinstance(data.get("sessions"), dict):
        raise TurnStateError("turn_state_corrupt")
    return data


def _save(ctx: Context, data: dict) -> None:
    write_json(ctx.turns_path, data)


def _log(ctx: Context, row: dict) -> None:
    try:
        append_jsonl(ctx.p("turns-log.jsonl"), dict(row, time=utc_now()))
    except OSError:
        pass


# ------------------------------------------------------------------ evidence
_CLAUDE_HINTS = (b'"promptSource"', b'"turn_duration"', b'"stop_hook_summary"', b"[Request interrupted")
_CODEX_HINTS = (b'"task_started"', b'"task_complete"', b'"turn_aborted"')


def _is_interrupt(o: dict) -> bool:
    c = (o.get("message") or {}).get("content") if isinstance(o.get("message"), dict) else None
    if isinstance(c, str):
        return c.startswith("[Request interrupted")
    if isinstance(c, list):
        return any(isinstance(x, dict) and str(x.get("text", "")).startswith("[Request interrupted") for x in c)
    return False


def claude_evidence(path: str) -> dict:
    """마지막 실제 프롬프트 위치와 그 뒤의 턴 종료 기록 위치(바이트 offset)."""
    ev = {"size": 0, "prompt_off": None, "end_off": None, "ended": False}
    try:
        with open(path, "rb") as f:
            data = f.read()
    except OSError:
        ev["unreadable"] = True
        return ev
    ev["size"] = len(data)
    off = 0
    for line in data.split(b"\n"):
        start, off = off, off + len(line) + 1
        if not any(h in line for h in _CLAUDE_HINTS):
            continue
        try:
            o = json.loads(line)
        except ValueError:
            continue
        if not isinstance(o, dict):
            continue
        t = o.get("type")
        if t == "user" and "promptSource" in o and not o.get("isCompactSummary") and not o.get("isSidechain"):
            ev["prompt_off"], ev["end_off"], ev["ended"] = start, None, False
        elif (t == "system" and o.get("subtype") in ("turn_duration", "stop_hook_summary")) or (
            t == "user" and _is_interrupt(o)
        ):
            if ev["prompt_off"] is not None:
                ev["end_off"], ev["ended"] = start, True
    return ev


def codex_evidence(path: str) -> dict:
    ev = {"size": 0, "prompt_off": None, "end_off": None, "ended": False, "turn_id": None}
    try:
        with open(path, "rb") as f:
            data = f.read()
    except OSError:
        ev["unreadable"] = True
        return ev
    ev["size"] = len(data)
    off = 0
    for line in data.split(b"\n"):
        start, off = off, off + len(line) + 1
        if not any(h in line for h in _CODEX_HINTS):
            continue
        try:
            o = json.loads(line)
        except ValueError:
            continue
        p = o.get("payload") if isinstance(o, dict) else None
        if not isinstance(p, dict):
            continue
        typ = p.get("type")
        if typ == "task_started":
            ev.update(prompt_off=start, end_off=None, ended=False, turn_id=p.get("turn_id"))
        elif typ in ("task_complete", "turn_aborted") and ev["prompt_off"] is not None:
            tid = p.get("turn_id")
            if tid is None or tid == ev["turn_id"]:
                ev["end_off"], ev["ended"] = start, True
    return ev


def evidence(tool: str, path: str) -> dict:
    return codex_evidence(path) if tool == "codex" else claude_evidence(path)


def combine(tool: str, ent: dict | None, ev: dict) -> tuple[str, str]:
    """hook 기록 + 원본 증거 → (상태, 근거)."""
    if ent is None:
        if ev["prompt_off"] is None:
            return IDLE, "no_turn_in_original"
        return (IDLE, "original_turn_ended") if ev["ended"] else (UNKNOWN, "open_turn_without_hook_state")
    st = ent.get("state")
    if st == ACTIVE:
        start = ent.get("start_off", 0)
        same_turn = tool != "codex" or not ent.get("turn_id") or ev.get("turn_id") == ent.get("turn_id")
        if ev["ended"] and ev["end_off"] is not None and ev["end_off"] >= start and same_turn:
            return IDLE, "original_turn_ended"
        return ACTIVE, "hook_active"
    if st == IDLE:
        idle_off = ent.get("idle_off", 0)
        if ev["prompt_off"] is not None and ev["prompt_off"] >= idle_off:
            # idle 표시 뒤에 hook 없이 시작된 턴(설정 미적용 등)
            return (IDLE, "original_turn_ended") if ev["ended"] else (UNKNOWN, "turn_started_without_hook")
        return IDLE, "hook_idle"
    if ev["ended"] and ev["end_off"] is not None and ev["end_off"] >= ent.get("start_off", 0):
        return IDLE, "original_turn_ended"
    return UNKNOWN, ent.get("why", "marked_unknown")


def effective_states(ctx: Context, targets=None) -> dict:
    """대상 세션 전체의 턴 상태. 상태 파일이 손상되면 모두 unknown."""
    from .discover import resolve_targets
    from .engine import load_state

    try:
        data = load_turns(ctx)
        corrupt = False
    except TurnStateError:
        data, corrupt = {"sessions": {}}, True
    if targets is None:
        targets = resolve_targets(ctx, load_state(ctx))
    out = {}
    for s in targets.sessions:
        if corrupt:
            out[s.key] = {"state": UNKNOWN, "why": "turn_state_corrupt"}
            continue
        ev = evidence(s.tool, s.main_path)
        st, why = combine(s.tool, data["sessions"].get(s.key), ev)
        out[s.key] = {"state": st, "why": why}
    for key, ent in data["sessions"].items():
        if key not in out and ent.get("state") != IDLE:
            # 원본을 찾지 못한 세션의 진행 중 표시는 무시하지 않는다
            out[key] = {"state": UNKNOWN, "why": "hook_" + str(ent.get("state")) + "_original_not_found"}
    return out


def busy_sessions(ctx: Context, targets=None) -> dict:
    return {k: v for k, v in effective_states(ctx, targets).items() if v["state"] != IDLE}


# --------------------------------------------------------------------- hooks
def _payload_session(tool: str, payload: dict):
    sid = payload.get("session_id")
    path = payload.get("transcript_path")
    if not isinstance(sid, str) or not sid:
        return None, None
    return f"{tool}/{sid}", (native_path(path) if isinstance(path, str) and path else None)


def _codex_key(sid_key: str, path: str | None) -> str:
    """Codex hook의 session_id가 원본 session_meta id와 다를 수 있어 원본 기준으로 맞춘다."""
    if not path:
        return sid_key
    from .discover import _read_codex_meta

    try:
        meta = _read_codex_meta(path)
    except OSError:
        meta = None
    return f"codex/{meta['id']}" if meta and meta.get("id") else sid_key


def prompt_hook(ctx: Context, tool: str) -> int:
    """UserPromptSubmit. 출력 없음(stdout은 모델 문맥에 들어간다). 실패하면 exit 2 + stderr 사유."""
    from .engine import _read_stdin_json, _register

    try:
        payload = _read_stdin_json()
        if payload.get("_invalid_input"):
            raise TurnStateError("invalid_hook_input")
        key, path = _payload_session(tool, payload)
        if key is None:
            raise TurnStateError("session_id_missing")
        if tool == "codex":
            key = _codex_key(key, path)
        size = os.path.getsize(path) if path and os.path.isfile(path) else 0
        with guard_lock(ctx, timeout=PROMPT_LOCK_TIMEOUT):
            data = load_turns(ctx)
            old = data["sessions"].get(key) or {}
            data["sessions"][key] = {
                "state": ACTIVE,
                "gen": int(old.get("gen", 0)) + 1,
                "turn_id": payload.get("turn_id"),
                "start_off": size,
                "transcript": path,
                "started": utc_now(),
            }
            _save(ctx, data)
        _log(ctx, {"event": "prompt", "session": key, "gen": data["sessions"][key]["gen"]})
        try:
            _register(ctx, tool, "UserPromptSubmit", payload)
        except OSError:
            pass
        return 0
    except LockTimeout:
        reason = "Git 자동화 작업이 진행 중이라 턴 보호 잠금을 얻지 못했습니다. 잠시 후 다시 보내세요."
    except Exception as e:  # noqa: BLE001
        reason = f"턴 보호 상태를 기록하지 못했습니다({getattr(e, 'args', [''])[0] or type(e).__name__})."
    try:
        from .engine import _record_error

        _record_error(ctx, tool, "UserPromptSubmit", "guard_failed")
    except Exception:  # noqa: BLE001
        pass
    sys.stderr.write(
        "[AI 세션 로깅] " + reason + " 프롬프트를 막았습니다. "
        "확인: python -I scripts/ai_logging/cli.py turns\n"
    )
    sys.stderr.flush()
    return 2


def _escaped(text: str) -> bytes:
    return json.dumps(text, ensure_ascii=False)[1:-1].encode("utf-8")


def _claude_stop_matches(path: str, start: int, message) -> bool:
    if not isinstance(message, str) or not message.strip() or not path:
        return False
    needle = _escaped(message[:200])
    deadline = time.monotonic() + STOP_MATCH_WAIT
    while True:
        try:
            with open(path, "rb") as f:
                f.seek(start)
                if needle in f.read():
                    return True
        except OSError:
            return False
        if time.monotonic() >= deadline:
            return False
        time.sleep(0.25)


def on_stop(ctx: Context, tool: str, payload: dict) -> str:
    """Stop: 이 턴의 Stop으로 확인되면 idle. 반환: marked_idle|unmatched|ignored."""
    key, path = _payload_session(tool, payload)
    if key is None:
        return "ignored"
    if tool == "codex":
        key = _codex_key(key, path)
    with guard_lock(ctx, timeout=10.0):
        data = load_turns(ctx)
        ent = data["sessions"].get(key)
        ev = evidence(tool, path) if path else {"prompt_off": None, "size": 0, "turn_id": None}
        if tool == "codex":
            tid = payload.get("turn_id")
            if ent and ent.get("turn_id"):
                ok = bool(tid) and tid == ent.get("turn_id")
            else:
                ok = bool(tid) and tid == ev.get("turn_id")
        else:
            if ent and ent.get("state") == ACTIVE:
                start = ent.get("start_off", 0)
            else:
                start = ev["prompt_off"] if ev["prompt_off"] is not None else 0
