                _mark(ctx, t["id"], "done", result=result, trigger=trigger)
                done_heads[t["id"]] = result.get("commit") or gitops.rev(root, "HEAD")
                ran.append(t["id"])
            return {"ran": len(ran), "reason": "ok", "done": ran}
    except LockTimeout:
        return {"ran": 0, "reason": "guard_lock_busy"}

