def default_context() -> Context:
    here = os.path.dirname(os.path.abspath(__file__))
    root = os.environ.get("AI_LOGGING_ROOT") or os.path.dirname(os.path.dirname(os.path.dirname(here)))
    home = os.path.expanduser("~")
    claude_home = (
        os.environ.get("AI_LOGGING_CLAUDE_HOME")
        or os.environ.get("CLAUDE_CONFIG_DIR")
        or os.path.join(home, ".claude")
    )
    codex_home = os.environ.get("AI_LOGGING_CODEX_HOME") or os.environ.get("CODEX_HOME") or os.path.join(home, ".codex")
    return Context(root=root, claude_home=claude_home, codex_home=codex_home)


class GitError(Exception):
    def __init__(self, args, code, stderr=b""):
        super().__init__(f"git {args[0] if args else ''} 실패(exit {code})")
        self.code = code
        self.stderr = stderr


def git(root: str, *args: str, timeout: float = 10.0):
    """git 명령의 표준 출력(문자열). 실패하면 None."""
    try:
        r = subprocess.run(["git", "-C", root, *args], capture_output=True, timeout=timeout, check=False)
    except (OSError, subprocess.SubprocessError):
        return None
    if r.returncode != 0:
        return None
    return r.stdout.decode("utf-8", "replace").strip()


def git_run(root: str, *args: str, input: bytes | None = None, env: dict | None = None, timeout: float = 120.0,
            check: bool = True) -> subprocess.CompletedProcess:
    """git 실행(바이트 입출력). check=True면 실패 시 GitError."""
    full_env = None
    if env:
        full_env = dict(os.environ)
        full_env.update(env)
    r = subprocess.run(["git", "-C", root, *args], input=input, capture_output=True, env=full_env, timeout=timeout,
                       check=False)
    if check and r.returncode != 0:
        raise GitError(args, r.returncode, r.stderr)
    return r
class Allowlist:
    def __init__(self, data: dict, raw: bytes = b""):
        self.raw = raw
        emails = data.get("emails", {})

        def _vals(items):
            return {(i if isinstance(i, str) else i["value"]).lower() for i in items}

        self.email_exact = _vals(emails.get("exact", []))
        self.email_domains = _vals(emails.get("domains", []))
        rnd = data.get("random_strings", {})
        self.random_patterns = [re.compile(p["pattern"].encode()) for p in rnd.get("patterns", [])]
        if rnd.get("json_keys"):
            # 키 이름만으로 면제하는 규칙은 지원하지 않는다(검토한 URL 문맥 url_contexts로 대체).
            raise ValueError("allowlist random_strings.json_keys is not supported; use url_contexts")
        self.url_contexts = list(rnd.get("url_contexts", []))
        kw = data.get("keywords", {})
        self.keyword_value_patterns = [re.compile(p["pattern"].encode()) for p in kw.get("value_patterns", [])]
        # 사람이 검토한 이미지·바이너리(대화 속 base64 이미지, 비텍스트 부속 파일)의 sha256
        self.image_hashes = {i["sha256"] for i in data.get("reviewed_binary", [])}

def load_allowlist(path: str) -> Allowlist:
    try:
        with open(path, "rb") as f:
            raw = f.read()
    except FileNotFoundError:
        return Allowlist({}, b"")
    return Allowlist(json.loads(raw.decode("utf-8")), raw)


def load_mask_entries(path: str) -> list[dict]:
    entries = []
    try:
        with open(path, "rb") as f:
            for line in f:
                line = line.strip()
                if line:
                    entries.append(json.loads(line.decode("utf-8")))
    except FileNotFoundError:
        pass
