def walk(obj, path, needle, out):
    if isinstance(obj, str):
        if needle in obj:
            out.append((path, obj.count(needle), len(obj)))
    elif isinstance(obj, dict):
        for k, v in obj.items():
            walk(v, path + [k], needle, out)
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            walk(v, path + [i], needle, out)


def meta(obj):
    m = {}
    for k in ("type", "subtype", "isMeta", "isCompactSummary", "isSidechain"):
        if k in obj:
            m[k] = obj[k]
    msg = obj.get("message") if isinstance(obj.get("message"), dict) else None
    if msg:
        m["role"] = msg.get("role")
        c = msg.get("content")
        if isinstance(c, list):
            m["blocks"] = [(b.get("type"), b.get("name")) for b in c if isinstance(b, dict)]
    p = obj.get("payload") if isinstance(obj.get("payload"), dict) else None
    if p:
        m["payload.type"] = p.get("type")
        for k in ("name", "role"):
